import React from 'react';

const getDoorArrowGeometry = (entryLine, entryDirectionPoint) => {
  if (!Array.isArray(entryLine) || entryLine.length !== 2 || !Array.isArray(entryDirectionPoint)) {
    return null;
  }

  const v0 = { x: Number(entryLine[0]?.[0]) || 0, y: Number(entryLine[0]?.[1]) || 0 };
  const v1 = { x: Number(entryLine[1]?.[0]) || 0, y: Number(entryLine[1]?.[1]) || 0 };
  const inside = { x: Number(entryDirectionPoint[0]) || 0, y: Number(entryDirectionPoint[1]) || 0 };
  const mid = { x: (v0.x + v1.x) / 2, y: (v0.y + v1.y) / 2 };
  const edgeLen = Math.hypot(v1.x - v0.x, v1.y - v0.y);
  if (edgeLen < 1e-6) return null;

  let nx = -(v1.y - v0.y) / edgeLen;
  let ny = (v1.x - v0.x) / edgeLen;
  const side = (inside.x - mid.x) * nx + (inside.y - mid.y) * ny;
  if (Math.abs(side) < 1e-6) return null;
  if (side < 0) {
    nx = -nx;
    ny = -ny;
  }
  const arrowLen = Math.max(0.02, Math.min(0.08, edgeLen * 0.275));

  return {
    edgeStart: v0,
    edgeEnd: v1,
    arrowStart: { x: mid.x - nx * arrowLen, y: mid.y - ny * arrowLen },
    arrowEnd: mid,
    mid,
    inside,
  };
};

const DoorLine = ({ zone }) => {
  const doorArrow = getDoorArrowGeometry(zone.entry_line, zone.entry_direction_point);
  if (!doorArrow) return null;

  return (
    <g key={`${zone.zone_id || zone.name}:door`}>
      <line
        x1={doorArrow.edgeStart.x}
        y1={doorArrow.edgeStart.y}
        x2={doorArrow.edgeEnd.x}
        y2={doorArrow.edgeEnd.y}
        stroke="rgba(0,0,0,0.9)"
        strokeWidth="4"
        vectorEffect="non-scaling-stroke"
      />
      <line
        x1={doorArrow.edgeStart.x}
        y1={doorArrow.edgeStart.y}
        x2={doorArrow.edgeEnd.x}
        y2={doorArrow.edgeEnd.y}
        stroke="#fbbf24"
        strokeWidth="2"
        vectorEffect="non-scaling-stroke"
      />
      <line
        x1={doorArrow.arrowStart.x}
        y1={doorArrow.arrowStart.y}
        x2={doorArrow.arrowEnd.x}
        y2={doorArrow.arrowEnd.y}
        stroke="rgba(0,0,0,0.95)"
        strokeWidth="4"
        vectorEffect="non-scaling-stroke"
      />
      <line
        x1={doorArrow.arrowStart.x}
        y1={doorArrow.arrowStart.y}
        x2={doorArrow.arrowEnd.x}
        y2={doorArrow.arrowEnd.y}
        stroke="#fbbf24"
        strokeWidth="2"
        markerEnd="url(#camera-door-arrowhead)"
        vectorEffect="non-scaling-stroke"
      />
      <circle
        cx={doorArrow.mid.x}
        cy={doorArrow.mid.y}
        r="0.006"
        fill="#fbbf24"
        stroke="rgba(0,0,0,0.95)"
        strokeWidth="1.25"
        vectorEffect="non-scaling-stroke"
      />
      <circle
        cx={doorArrow.inside.x}
        cy={doorArrow.inside.y}
        r="0.005"
        fill="#fbbf24"
        stroke="rgba(0,0,0,0.95)"
        strokeWidth="1"
        vectorEffect="non-scaling-stroke"
      />
    </g>
  );
};

export const ZoneOverlay = ({ zones = [] }) => {
  const drawableZones = zones.filter((zone) => (
    zone.zone_type === 'door'
      ? Array.isArray(zone.entry_line) && Array.isArray(zone.entry_direction_point)
      : Array.isArray(zone.polygons) && zone.polygons.length > 0
  ));
  if (!drawableZones.length) return null;

  return (
    <svg className="camera-zone-overlay" viewBox="0 0 1 1" preserveAspectRatio="none" aria-hidden="true">
      <defs>
        <marker id="camera-door-arrowhead" markerWidth="8" markerHeight="8" refX="8" refY="4" orient="auto" markerUnits="strokeWidth">
          <path d="M 0 0 L 8 4 L 0 8 z" fill="#fbbf24" stroke="rgba(0,0,0,0.95)" strokeWidth="1" />
        </marker>
      </defs>
      {drawableZones.flatMap((zone) => {
        if (zone.zone_type === 'door') {
          return <DoorLine key={`${zone.zone_id || zone.name}:door`} zone={zone} />;
        }
        return (zone.polygons || []).map((polygon, index) => {
          if (!Array.isArray(polygon) || polygon.length < 3) return null;
          const points = polygon
            .map((point) => `${Number(point[0]) || 0},${Number(point[1]) || 0}`)
            .join(' ');
          return (
            <g key={`${zone.zone_id || zone.name}:${index}`}>
              <polygon
                points={points}
                fill="none"
                stroke={zone.color || '#00ff00'}
                strokeWidth="1.25"
                vectorEffect="non-scaling-stroke"
              />
            </g>
          );
        });
      })}
    </svg>
  );
};
