import React, { useState } from 'react';
import { Eye, EyeOff } from 'lucide-react';
import { API_ENDPOINT_MODES } from '../../connection';

function LoginScreen({
  onLogin,
  loading,
  error,
  apiEndpoint,
  localDeviceIdInput,
  onLocalDeviceIdInputChange,
  customEndpointInput,
  endpointError,
  onEndpointModeChange,
  onLocalEndpointApply,
  onCustomEndpointInputChange,
  onCustomEndpointBlur,
  onCustomEndpointApply,
}) {
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [stayLoggedIn, setStayLoggedIn] = useState(false);

  const handleSubmit = async (event) => {
    event.preventDefault();
    await onLogin(password, stayLoggedIn);
  };

  return (
    <div className="app-loading" style={{ minHeight: '100vh' }}>
      <div
        style={{
          width: '100%',
          maxWidth: 420,
          background: 'rgba(255,255,255,0.85)',
          border: '1px solid rgba(0, 137, 123, 0.15)',
          borderRadius: 16,
          padding: 24,
          boxShadow: '0 12px 36px rgba(0, 150, 136, 0.2)',
        }}
      >
        <h2 className="page-title" style={{ fontSize: 26, marginBottom: 8 }}>NVR Login</h2>
        <p className="page-subtitle" style={{ marginBottom: 16 }}>Enter API password to continue.</p>

        <div className="api-endpoint-control login-endpoint-control">
          <label className="api-endpoint-label" htmlFor="login-api-endpoint-mode">
            Network endpoint
          </label>
          <select
            id="login-api-endpoint-mode"
            className="api-endpoint-select"
            value={apiEndpoint.mode}
            onChange={onEndpointModeChange}
          >
            {apiEndpoint.options.map(option => (
              <option
                key={option.value}
                value={option.value}
                disabled={!option.baseUrl && ![API_ENDPOINT_MODES.LOCAL, API_ENDPOINT_MODES.CUSTOM].includes(option.value)}
              >
                {option.baseUrl ? `${option.label} - ${option.baseUrl}` : `${option.label} (unavailable)`}
              </option>
            ))}
          </select>

          {apiEndpoint.mode === API_ENDPOINT_MODES.LOCAL && !apiEndpoint.localPathBaseUrl && (
            <div className="api-endpoint-custom">
              <input
                type="text"
                inputMode="numeric"
                className="api-endpoint-input"
                value={localDeviceIdInput}
                onChange={(event) => onLocalDeviceIdInputChange(event.target.value)}
                placeholder="Device ID (1-9999)"
                aria-label="Device ID"
                autoComplete="off"
              />
              <button type="button" className="api-endpoint-apply" onClick={onLocalEndpointApply}>
                Apply
              </button>
            </div>
          )}

          {apiEndpoint.mode === API_ENDPOINT_MODES.CUSTOM && (
            <div className="api-endpoint-custom">
              <input
                type="text"
                className="api-endpoint-input"
                value={customEndpointInput}
                onChange={(event) => onCustomEndpointInputChange(event.target.value)}
                onBlur={onCustomEndpointBlur}
                placeholder="https://example.com"
                aria-label="Custom backend URL"
                autoComplete="off"
                spellCheck="false"
              />
              <button type="button" className="api-endpoint-apply" onClick={onCustomEndpointApply}>
                Apply
              </button>
            </div>
          )}

          <span className="api-endpoint-current">Using: {apiEndpoint.baseUrl || 'Not configured'}</span>
          {endpointError ? <span className="api-endpoint-error">{endpointError}</span> : null}
        </div>

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label className="form-label" htmlFor="password">Password</label>
            <div className="login-password-control">
              <input
                id="password"
                type={showPassword ? 'text' : 'password'}
                className="form-control"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Enter password"
                autoComplete="current-password"
                required
              />
              <button
                type="button"
                className="login-password-toggle"
                onClick={() => setShowPassword((visible) => !visible)}
                aria-label={showPassword ? 'Hide password' : 'Show password'}
                aria-pressed={showPassword}
              >
                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
          </div>

          <label className="login-stay-logged-in">
            <input
              type="checkbox"
              checked={stayLoggedIn}
              onChange={(event) => setStayLoggedIn(event.target.checked)}
            />
            <span>Stay logged in</span>
          </label>

          {error ? (
            <p style={{ color: '#d32f2f', marginBottom: 12 }}>{error}</p>
          ) : null}

          <button type="submit" className="btn btn-primary" disabled={loading}>
            {loading ? 'Signing in...' : 'Sign in'}
          </button>
        </form>
      </div>
    </div>
  );
}

export default LoginScreen;
