import {
  API_TIMEOUT_MS,
  apiClient,
  getApiBaseUrl,
  getStoredToken,
} from '../api';

const websocketBaseUrl = () => {
  const apiBaseUrl = new URL(getApiBaseUrl());
  apiBaseUrl.protocol = apiBaseUrl.protocol === 'https:' ? 'wss:' : 'ws:';
  return apiBaseUrl.origin;
};

const authenticatedWebSocketUrl = (path, query = {}) => {
  const base = `${websocketBaseUrl()}${path}`;
  const token = getStoredToken();
  const params = new URLSearchParams(query);
  if (token) params.set('access_token', token);
  const queryString = params.toString();
  return queryString ? `${base}?${queryString}` : base;
};

const parseSdpResponse = (response, errorMessage) => {
  const sessionId = response.headers['x-webrtc-session-id'];
  if (!response.data || !sessionId) throw new Error(errorMessage);
  return { answerSdp: response.data, sessionId };
};

export const transportApi = {
  getIceConfig: async () => {
    const response = await apiClient.get('/transports/webrtc/config', {
      timeout: API_TIMEOUT_MS.WEBRTC_TRANSPORT,
    });
    return response.data || {};
  },

  startCameraWebRtc: async (cameraId, offerSdp, iceGathering = null) => {
    const headers = { 'Content-Type': 'application/sdp' };
    if (iceGathering) {
      headers['X-WebRTC-ICE-Gathering-Ms'] = String(iceGathering.elapsedMs);
      headers['X-WebRTC-ICE-Gathering-Complete'] = String(iceGathering.complete);
    }
    const response = await apiClient.post(
      `/transports/webrtc/cameras/${cameraId}`,
      offerSdp,
      {
        headers,
        responseType: 'text',
        timeout: API_TIMEOUT_MS.WEBRTC_TRANSPORT,
      },
    );
    return parseSdpResponse(response, 'Invalid camera WebRTC negotiation response');
  },

  stopCameraWebRtc: (cameraId, sessionId) => apiClient.delete(
    `/transports/webrtc/cameras/${cameraId}/sessions/${sessionId}`,
    { timeout: API_TIMEOUT_MS.WEBRTC_TRANSPORT },
  ),

  startRecordingWebRtc: async (recordingId, offerSdp, overlay = false) => {
    const response = await apiClient.post(
      `/transports/webrtc/recordings/${recordingId}`,
      offerSdp,
      {
        params: overlay ? { overlay: true } : undefined,
        headers: { 'Content-Type': 'application/sdp' },
        responseType: 'text',
        timeout: API_TIMEOUT_MS.WEBRTC_TRANSPORT,
      },
    );
    return parseSdpResponse(response, 'Invalid recorded WebRTC negotiation response');
  },

  stopRecordingWebRtc: (recordingId, sessionId) => apiClient.delete(
    `/transports/webrtc/recordings/${recordingId}/sessions/${sessionId}`,
    { timeout: API_TIMEOUT_MS.WEBRTC_TRANSPORT },
  ),

  startWebRtcDataChannel: async (offerSdp) => {
    const response = await apiClient.post(
      '/transports/webrtc/data-channel',
      { sdp: offerSdp },
      { timeout: API_TIMEOUT_MS.WEBRTC_TRANSPORT },
    );
    return response.data;
  },

  stopWebRtcDataChannel: (sessionId) => apiClient.delete(
    `/transports/webrtc/data-channel/sessions/${sessionId}`,
    { timeout: API_TIMEOUT_MS.WEBRTC_TRANSPORT },
  ),

  startPersistentClipWebRtc: async (offerSdp, clientId) => {
    const response = await apiClient.post(
      '/transports/webrtc/clip-channel',
      { sdp: offerSdp, client_id: clientId },
      { timeout: API_TIMEOUT_MS.WEBRTC_TRANSPORT },
    );
    return response.data;
  },

  stopPersistentClipWebRtc: (sessionId) => apiClient.delete(
    `/transports/webrtc/clip-channel/sessions/${sessionId}`,
    { timeout: API_TIMEOUT_MS.WEBRTC_TRANSPORT },
  ),

  getCameraWebSocketUrl: (cameraId) => authenticatedWebSocketUrl(
    `/api/transports/websocket/cameras/${encodeURIComponent(cameraId)}`,
  ),

  getCameraFmp4WebSocketUrl: (cameraId) => authenticatedWebSocketUrl(
    `/api/transports/websocket/cameras/${encodeURIComponent(cameraId)}/fmp4`,
  ),

  getDataChannelWebSocketUrl: (includeRecordingEvents = false) => authenticatedWebSocketUrl(
    '/api/transports/websocket/data-channel',
    { recordings: includeRecordingEvents ? '1' : '0' },
  ),
};
