import React, { useCallback, useEffect, useRef, useState } from 'react';
import Hls from 'hls.js';
import { RefreshCw } from 'lucide-react';
import { api } from '../../api';
import {
  connectCameraWebRtc,
  connectCameraWsMse,
  resetCameraWebRtcSession,
} from '../../transports/camera';
import zonesApi from '../../zonesApi';
import { ZoneOverlay } from './draw_utils';

export const DEFAULT_LIVE_STREAM_MODES = ['webrtc', 'ws', 'hls', 'mjpeg'];
const STREAM_START_TIMEOUT_MS = 8000;
const WEBRTC_FIRST_FRAME_TIMEOUT_MS = 20000;
const WEBRTC_SESSION_RETENTION_MS = 30_000;

const normalizeLiveStreamMode = (mode, allowedModes = DEFAULT_LIVE_STREAM_MODES) => (
  allowedModes.includes(String(mode || '').toLowerCase())
    ? String(mode || '').toLowerCase()
    : allowedModes[0]
);

const getNextFallbackMode = (mode, allowedModes) => {
  const index = allowedModes.indexOf(normalizeLiveStreamMode(mode, allowedModes));
  return allowedModes[index + 1] || null;
};

export const AUDIO_TOGGLE_STYLE = {
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  width: '32px',
  height: '32px',
  borderRadius: '8px',
  border: '1px solid #2f3743',
  cursor: 'pointer',
};

const AUDIO_PANEL_STYLE = {
  display: 'inline-flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  width: '140px',
  flex: '0 0 auto',
  padding: '4px 6px',
  border: '1px solid rgba(148,163,184,0.25)',
  borderRadius: '10px',
  background: 'rgba(10,14,20,0.35)',
};

const AUDIO_PLAYER_STYLE = { width: '100%', maxWidth: '100%', height: '22px' };

// Backend always streams raw PCM wrapped in a WAV header — format is fixed.
const AUDIO_STREAM_FORMAT = 'wav';

export const SENSITIVITY_LEVEL = 5;
export const DEFAULT_SENSITIVITY = 2;

const getCameraAspectRatio = (resolution) => {
  const match = /^([0-9]+)x([0-9]+)$/i.exec(resolution || '');
  if (!match) {
    return '16 / 9';
  }
  const width = parseInt(match[1], 10) || 16;
  const height = parseInt(match[2], 10) || 9;
  return `${width} / ${height}`;
};

export const CameraAudioPanel = ({ camera }) => {
  const audioRef = useRef(null);
  const isOnline = camera.status === 'online' || camera.status === 'recording';
  const shouldRenderAudio = isOnline && Boolean(camera.audio_enabled);
  const [audioPlaybackFormat] = useState(AUDIO_STREAM_FORMAT);
  const [activeAudioUrl, setActiveAudioUrl] = useState('');

  // Reset audio URL when camera changes
  useEffect(() => {
    setActiveAudioUrl('');
  }, [camera.id]);

  // Start audio when camera comes online
  useEffect(() => {
    if (!shouldRenderAudio) {
      // Stop audio if camera goes offline
      setActiveAudioUrl('');
      const audioEl = audioRef.current;
      if (audioEl) {
        audioEl.pause();
        audioEl.src = '';
      }
      return;
    }

    // Camera is online and audio enabled - start audio stream
    const streamUrl = api.getCameraAudioStreamUrl(camera.id, audioPlaybackFormat);
    setActiveAudioUrl(streamUrl);
    
    // Auto-play when audio source is set
    setTimeout(() => {
      const audioEl = audioRef.current;
      if (audioEl && streamUrl) {
        audioEl.play().catch(() => {
          console.log('Audio autoplay blocked - user must click play');
        });
      }
    }, 500);
  }, [shouldRenderAudio, camera.id, audioPlaybackFormat]);

  if (!shouldRenderAudio) {
    return null;
  }

  return (
    <div style={AUDIO_PANEL_STYLE}>
      <audio
        ref={audioRef}
        src={activeAudioUrl}
        controls={true}
        autoPlay={true}
        muted={false}
        preload="metadata"
        style={AUDIO_PLAYER_STYLE}
      />
    </div>
  );
};

export const CameraVideoPanel = ({
  camera,
  variant = 'primary',
  streamMode = 'mjpeg',
  minimalMode = false,
  activeStreamModes = DEFAULT_LIVE_STREAM_MODES,
  onEffectiveStreamModeChange,
}) => {
  const isOnline = camera.status === 'online' || camera.status === 'recording';
  const videoRef = useRef(null);
  const hlsRef = useRef(null);
  const allowedStreamModes = activeStreamModes.length > 0 ? activeStreamModes : DEFAULT_LIVE_STREAM_MODES;
  const configuredStreamMode = normalizeLiveStreamMode(streamMode, allowedStreamModes);
  const [effectiveStreamMode, setEffectiveStreamMode] = useState(configuredStreamMode);
  const [streamStarting, setStreamStarting] = useState(false);
  const [reconnectGeneration, setReconnectGeneration] = useState(0);
  const [zones, setZones] = useState([]);
  const [pageVisible, setPageVisible] = useState(() => document.visibilityState !== 'hidden');

  useEffect(() => {
    const handleVisibilityChange = () => {
      setPageVisible(document.visibilityState !== 'hidden');
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
  }, []);

  const reconnectStream = useCallback(() => {
    resetCameraWebRtcSession(camera.id);
    setEffectiveStreamMode(configuredStreamMode);
    setStreamStarting(true);
    setReconnectGeneration((generation) => generation + 1);
  }, [camera.id, configuredStreamMode]);

  const activateFallback = useCallback((failedMode, error) => {
    if (variant !== 'primary') return false;
    const nextMode = getNextFallbackMode(failedMode, allowedStreamModes);
    if (!nextMode) return false;
    console.warn(
      `Camera ${camera.id} ${failedMode} stream failed; falling back to ${nextMode}`,
      error || '',
    );
    setEffectiveStreamMode((currentMode) => (
      currentMode === failedMode ? nextMode : currentMode
    ));
    return true;
  }, [allowedStreamModes, camera.id, variant]);

  useEffect(() => {
    setEffectiveStreamMode(configuredStreamMode);
    setStreamStarting(false);
  }, [camera.id, configuredStreamMode, isOnline, minimalMode]);

  useEffect(() => {
    if (variant === 'primary') {
      onEffectiveStreamModeChange?.(effectiveStreamMode);
    }
  }, [effectiveStreamMode, onEffectiveStreamModeChange, variant]);

  useEffect(() => {
    if (variant !== 'primary' || !isOnline) {
      setZones([]);
      return;
    }
    let cancelled = false;
    zonesApi.getCameraZones(camera.id)
      .then((response) => {
        if (!cancelled) setZones(response?.data?.zones || []);
      })
      .catch(() => {
        if (!cancelled) setZones([]);
      });
    return () => {
      cancelled = true;
    };
  }, [camera.id, isOnline, variant]);

  useEffect(() => {
    if (variant !== 'primary') return undefined;
    const onZonesUpdated = (event) => {
      const detail = event?.detail || {};
      if (detail.cameraId !== camera.id) return;
      setZones(detail.zones || []);
    };
    window.addEventListener('zones:updated', onZonesUpdated);
    return () => {
      window.removeEventListener('zones:updated', onZonesUpdated);
    };
  }, [camera.id, variant]);

  // HLS setup / teardown
  useEffect(() => {
    if (variant !== 'primary' || effectiveStreamMode !== 'hls' || !isOnline) return;
    const videoEl = videoRef.current;
    if (!videoEl) return;

    setStreamStarting(true);
    const manifestUrl = api.appendQueryParams(api.getCameraHlsManifestUrl(camera.id), {
      reconnect: reconnectGeneration,
    });
    let started = false;
    const startTimeout = window.setTimeout(() => {
      if (!started) {
        setStreamStarting(false);
        activateFallback('hls', new Error('HLS playback did not start'));
      }
    }, STREAM_START_TIMEOUT_MS);
    const handlePlaying = () => {
      started = true;
      setStreamStarting(false);
      window.clearTimeout(startTimeout);
    };
    const handleVideoError = () => {
      setStreamStarting(false);
      activateFallback('hls', videoEl.error || new Error('HLS video error'));
    };
    videoEl.addEventListener('playing', handlePlaying);
    videoEl.addEventListener('error', handleVideoError);
    const cleanupVideoListeners = () => {
      window.clearTimeout(startTimeout);
      videoEl.removeEventListener('playing', handlePlaying);
      videoEl.removeEventListener('error', handleVideoError);
    };

    if (Hls.isSupported()) {
      const hls = new Hls({ liveSyncDurationCount: 1, liveMaxLatencyDurationCount: 3 });
      hlsRef.current = hls;
      hls.loadSource(manifestUrl);
      hls.attachMedia(videoEl);
      hls.on(Hls.Events.MANIFEST_PARSED, () => videoEl.play().catch(() => {}));
      hls.on(Hls.Events.ERROR, (_, data) => {
        if (data?.fatal) activateFallback('hls', data);
      });
      return () => {
        cleanupVideoListeners();
        hls.destroy();
        hlsRef.current = null;
      };
    } else if (videoEl.canPlayType('application/vnd.apple.mpegurl')) {
      // Native HLS (Safari)
      videoEl.src = manifestUrl;
      videoEl.play().catch(() => {});
      return cleanupVideoListeners;
    }
    setStreamStarting(false);
    activateFallback('hls', new Error('HLS is not supported'));
    return cleanupVideoListeners;
  }, [effectiveStreamMode, isOnline, camera.id, variant, activateFallback, reconnectGeneration]);

  // WebRTC setup / teardown
  useEffect(() => {
    if (
      variant !== 'primary'
      || effectiveStreamMode !== 'webrtc'
      || !isOnline
      || !pageVisible
    ) return;
    const videoEl = videoRef.current;
    if (!videoEl) return;

    setStreamStarting(true);
    let close = null;
    let cancelled = false;
    let started = false;
    let firstFrameTimeout = null;
    const handlePlaying = () => {
      started = true;
      setStreamStarting(false);
      if (firstFrameTimeout !== null) window.clearTimeout(firstFrameTimeout);
    };
    const handleVideoError = () => {
      setStreamStarting(false);
      activateFallback('webrtc', videoEl.error || new Error('WebRTC video error'));
    };
    videoEl.addEventListener('playing', handlePlaying);
    videoEl.addEventListener('error', handleVideoError);
    connectCameraWebRtc({
      cameraId: camera.id,
      audio: Boolean(camera.audio_enabled),
      videoElement: videoEl,
      onFailure: (error) => {
        if (cancelled) return;
        setStreamStarting(false);
        if (!activateFallback('webrtc', error)) {
          console.error(`WebRTC stream failed for ${camera.id}:`, error);
        }
      },
      onCloseReady: (closeConnection) => {
        if (cancelled) closeConnection();
        else close = closeConnection;
      },
      onNegotiated: () => {
        if (started || cancelled) return;
        firstFrameTimeout = window.setTimeout(() => {
          if (!started && !cancelled) {
            setStreamStarting(false);
            activateFallback('webrtc', new Error('WebRTC negotiated but no first frame arrived'));
          }
        }, WEBRTC_FIRST_FRAME_TIMEOUT_MS);
      },
      retentionMs: WEBRTC_SESSION_RETENTION_MS,
    }).then((closeConnection) => {
      if (cancelled) closeConnection();
      else close = closeConnection;
    }).catch((error) => {
      if (cancelled) return;
      setStreamStarting(false);
      if (!activateFallback('webrtc', error)) {
        console.error(`WebRTC stream failed for ${camera.id}:`, error);
      }
    });

    return () => {
      cancelled = true;
      if (firstFrameTimeout !== null) window.clearTimeout(firstFrameTimeout);
      videoEl.removeEventListener('playing', handlePlaying);
      videoEl.removeEventListener('error', handleVideoError);
      if (close) close();
    };
  }, [effectiveStreamMode, isOnline, camera.id, camera.audio_enabled, variant, activateFallback, reconnectGeneration, pageVisible]);

  // WS-fMP4/MSE setup / teardown
  useEffect(() => {
    if (variant !== 'primary' || effectiveStreamMode !== 'ws' || !isOnline) return;
    const videoEl = videoRef.current;
    if (!videoEl) return;
    setStreamStarting(true);
    let started = false;
    const startTimeout = window.setTimeout(() => {
      if (!started) {
        setStreamStarting(false);
        activateFallback('ws', new Error('WebSocket playback did not start'));
      }
    }, STREAM_START_TIMEOUT_MS);
    const handlePlaying = () => {
      started = true;
      setStreamStarting(false);
      window.clearTimeout(startTimeout);
    };
    const handleVideoError = () => {
      setStreamStarting(false);
      activateFallback('ws', videoEl.error || new Error('WebSocket video error'));
    };
    videoEl.addEventListener('playing', handlePlaying);
    videoEl.addEventListener('error', handleVideoError);
    const cleanupConnection = connectCameraWsMse({
      cameraId: camera.id,
      videoElement: videoEl,
      onUnsupported: () => activateFallback('ws', new Error('WebSocket MSE is not supported')),
    });
    return () => {
      window.clearTimeout(startTimeout);
      videoEl.removeEventListener('playing', handlePlaying);
      videoEl.removeEventListener('error', handleVideoError);
      cleanupConnection();
    };
  }, [effectiveStreamMode, isOnline, camera.id, variant, activateFallback, reconnectGeneration]);

  const mediaStyle = {
    width: '100%',
    height: 'auto',
    aspectRatio: getCameraAspectRatio(camera.resolution),
    objectFit: 'contain',
    background: '#000',
  };
  const streamLoadingLabel = effectiveStreamMode === 'webrtc'
    ? 'Connecting to video stream...'
    : 'Loading stream...';
  const reconnectButton = variant === 'primary' ? (
    <button
      type="button"
      className="camera-stream-reconnect"
      onClick={reconnectStream}
      disabled={streamStarting}
      title="Reconnect this camera stream"
      aria-label={`Reconnect ${camera.name} stream`}
    >
      <RefreshCw size={16} className={streamStarting ? 'camera-stream-reconnect-icon--spinning' : ''} />
    </button>
  ) : null;

  if (!isOnline) {
    return (
      <img
        src={`${api.getBlankStreamUrl(camera.id)}`}
        alt={`Camera ${camera.name}`}
        className="camera-stream"
        style={mediaStyle}
      />
    );
  }

  // Support view always uses processing stream (MJPEG)
  if (variant === 'support') {
    return (
      <img
        key={`${camera.id}:support`}
        src={api.appendQueryParams(api.getProcessingStreamUrl(camera.id), { view: 'support' })}
        alt={`Support view for ${camera.name}`}
        className="camera-stream"
        style={mediaStyle}
      />
    );
  }

  if (effectiveStreamMode === 'hls' || effectiveStreamMode === 'webrtc') {
    return (
      <div className="camera-stream-shell">
        <video
          ref={videoRef}
          key={`${camera.id}:${effectiveStreamMode}`}
          className="camera-stream"
          style={mediaStyle}
          muted={!camera.audio_enabled}
          controls={Boolean(camera.audio_enabled)}
          autoPlay
          playsInline
        />
        <ZoneOverlay zones={zones} />
        {reconnectButton}
        {streamStarting && (
          <div className="camera-stream-loading" aria-live="polite">
            <span className="loading" aria-hidden="true"></span>
            <span>{streamLoadingLabel}</span>
          </div>
        )}
      </div>
    );
  }

  if (effectiveStreamMode === 'ws') {
    return (
      <div className="camera-stream-shell">
        <video
          ref={videoRef}
          key={`${camera.id}:ws-mse`}
          className="camera-stream"
          style={mediaStyle}
          muted={!camera.audio_enabled}
          controls={Boolean(camera.audio_enabled)}
          autoPlay
          playsInline
        />
        <ZoneOverlay zones={zones} />
        {reconnectButton}
        {streamStarting && (
          <div className="camera-stream-loading" aria-live="polite">
            <span className="loading" aria-hidden="true"></span>
            <span>{streamLoadingLabel}</span>
          </div>
        )}
      </div>
    );
  }

  // Default: MJPEG
  return (
    <div className="camera-stream-shell">
      <img
        key={`${camera.id}:mjpeg:${reconnectGeneration}`}
        src={api.appendQueryParams(api.getCameraMjpegStreamUrl(camera.id), {
          reconnect: reconnectGeneration,
        })}
        alt={`Camera ${camera.name}`}
        className="camera-stream"
        style={mediaStyle}
        onLoad={() => setStreamStarting(false)}
        onError={() => setStreamStarting(false)}
      />
      <ZoneOverlay zones={zones} />
      {reconnectButton}
    </div>
  );
};
