import { transportApi } from './api';
import { createReceivePeer, waitForIceGathering } from './webrtc';

const CLIENT_ID_KEY = 'motion-analysis-clip-client-id';
const REQUEST_TIMEOUT_MS = 120000;

const randomId = () => (
  window.crypto?.randomUUID?.()
  || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`
);

const getBrowserClientId = () => {
  try {
    const existing = window.localStorage.getItem(CLIENT_ID_KEY);
    if (existing) return existing;
    const clientId = randomId();
    window.localStorage.setItem(CLIENT_ID_KEY, clientId);
    return clientId;
  } catch (_error) {
    return randomId();
  }
};

const errorWithCode = (message, code) => {
  const error = new Error(message);
  error.code = code;
  return error;
};

/**
 * One Event-page WebRTC peer carrying persistent audio/video tracks and an
 * ordered data channel used to switch the file feeding those tracks.
 */
export const createPersistentClipChannel = ({ turnOnly = false, onState } = {}) => {
  let peer = null;
  let channel = null;
  let sessionId = null;
  let closed = false;
  let revoked = false;
  let activeElement = null;
  let activeRecordingId = null;
  let activeOverlay = false;
  let playGeneration = 0;
  const stream = new MediaStream();
  const pending = new Map();

  let resolveReady;
  let rejectReady;
  const ready = new Promise((resolve, reject) => {
    resolveReady = resolve;
    rejectReady = reject;
  });

  const notify = (state, detail = {}) => {
    if (onState) onState({ state, ...detail });
  };

  const rejectPending = (error) => {
    pending.forEach(({ reject, timer }) => {
      window.clearTimeout(timer);
      reject(error);
    });
    pending.clear();
  };

  const detach = (element = activeElement) => {
    if (!element) return;
    if (element.srcObject === stream) element.srcObject = null;
    if (element === activeElement) activeElement = null;
  };

  const attach = async (element) => {
    if (!element || closed || revoked) return;
    if (activeElement && activeElement !== element) detach(activeElement);
    element.removeAttribute('src');
    element.srcObject = stream;
    activeElement = element;
    await element.play();
  };

  const sendRequest = async (type, payload = {}) => {
    await ready;
    if (closed) throw errorWithCode('Clip session is closed', 'CLIP_SESSION_CLOSED');
    if (revoked) {
      throw errorWithCode(
        'Playback moved to a newer tab for this browser client',
        'CLIP_SESSION_REPLACED',
      );
    }
    if (!channel || channel.readyState !== 'open') {
      throw errorWithCode('Clip control channel is not open', 'CLIP_CHANNEL_CLOSED');
    }
    const requestId = randomId();
    return new Promise((resolve, reject) => {
      const timer = window.setTimeout(() => {
        pending.delete(requestId);
        reject(errorWithCode('Timed out while preparing the clip', 'CLIP_REQUEST_TIMEOUT'));
      }, REQUEST_TIMEOUT_MS);
      pending.set(requestId, { resolve, reject, timer, type });
      channel.send(JSON.stringify({
        type,
        request_id: requestId,
        ...payload,
      }));
    });
  };

  const handleMessage = (event) => {
    let message;
    try {
      message = JSON.parse(event.data);
    } catch (_error) {
      return;
    }

    if (message.type === 'clip.revoked') {
      revoked = true;
      detach();
      const error = errorWithCode(
        message.payload?.reason || 'Playback moved to a newer tab',
        'CLIP_SESSION_REPLACED',
      );
      rejectReady(error);
      rejectPending(error);
      notify('revoked', { error });
      return;
    }

    const request = pending.get(message.request_id);
    if (!request) return;
    if (message.type === 'clip.failed') {
      window.clearTimeout(request.timer);
      pending.delete(message.request_id);
      request.reject(errorWithCode(
        message.payload?.message || 'Clip playback failed',
        'CLIP_PLAY_FAILED',
      ));
      return;
    }
    if (
      (request.type === 'clip.play' && message.type === 'clip.ready')
      || (request.type === 'clip.stop' && message.type === 'clip.stopped')
    ) {
      window.clearTimeout(request.timer);
      pending.delete(message.request_id);
      if (message.type === 'clip.ready') notify('playing', message.payload);
      request.resolve(message.payload || {});
    }
  };

  const close = () => {
    if (closed) return;
    closed = true;
    playGeneration += 1;
    detach();
    const error = errorWithCode('Clip session is closed', 'CLIP_SESSION_CLOSED');
    rejectReady(error);
    rejectPending(error);
    if (channel && channel.readyState !== 'closed') channel.close();
    if (peer) peer.close();
    stream.getTracks().forEach((track) => track.stop());
    if (sessionId) transportApi.stopPersistentClipWebRtc(sessionId).catch(() => {});
    notify('closed');
  };

  const connect = async () => {
    try {
      notify('connecting');
      peer = await createReceivePeer({ audio: true, turnOnly });
      if (closed) {
        peer.close();
        return;
      }
      channel = peer.createDataChannel('clip-control', { ordered: true });
      channel.onmessage = handleMessage;
      channel.onclose = () => {
        if (closed || revoked) return;
        const error = errorWithCode('Clip control channel closed', 'CLIP_CHANNEL_CLOSED');
        rejectReady(error);
        rejectPending(error);
        notify('failed', { error });
      };
      peer.ontrack = (event) => {
        if (closed) {
          event.track.stop();
          return;
        }
        if (!stream.getTracks().some((track) => track.id === event.track.id)) {
          stream.addTrack(event.track);
        }
      };
      peer.onconnectionstatechange = () => {
        if (closed || !['failed', 'disconnected'].includes(peer.connectionState)) return;
        const error = errorWithCode(
          `Clip WebRTC ${peer.connectionState}`,
          'CLIP_CONNECTION_FAILED',
        );
        rejectReady(error);
        rejectPending(error);
        notify('failed', { error });
      };

      const channelOpen = new Promise((resolve, reject) => {
        channel.onopen = resolve;
        channel.onerror = () => reject(
          errorWithCode('Clip control channel failed', 'CLIP_CHANNEL_FAILED'),
        );
      });
      const offer = await peer.createOffer();
      await peer.setLocalDescription(offer);
      await waitForIceGathering(peer);
      const response = await transportApi.startPersistentClipWebRtc(
        peer.localDescription.sdp,
        getBrowserClientId(),
      );
      sessionId = response.session_id;
      if (closed) {
        transportApi.stopPersistentClipWebRtc(sessionId).catch(() => {});
        return;
      }
      await peer.setRemoteDescription({ type: 'answer', sdp: response.sdp });
      await channelOpen;
      resolveReady();
      notify('ready', { sessionId });
    } catch (error) {
      rejectReady(error);
      rejectPending(error);
      notify('failed', { error });
      if (!closed) close();
    }
  };

  const play = async ({ recordingId, overlay = false, videoElement }) => {
    const generation = ++playGeneration;
    await ready;
    if (closed) throw errorWithCode('Clip session is closed', 'CLIP_SESSION_CLOSED');
    if (revoked) {
      throw errorWithCode(
        'Playback moved to a newer tab for this browser client',
        'CLIP_SESSION_REPLACED',
      );
    }
    if (
      activeRecordingId === String(recordingId)
      && activeOverlay === Boolean(overlay)
    ) {
      if (generation === playGeneration) await attach(videoElement);
      return;
    }

    detach();
    activeRecordingId = null;
    await sendRequest('clip.play', {
      recording_id: String(recordingId),
      overlay: Boolean(overlay),
    });
    if (generation !== playGeneration) return;
    activeRecordingId = String(recordingId);
    activeOverlay = Boolean(overlay);
    await attach(videoElement);
  };

  const stop = async () => {
    playGeneration += 1;
    activeRecordingId = null;
    detach();
    try {
      await sendRequest('clip.stop');
    } catch (error) {
      if (!closed && error.code !== 'CLIP_SESSION_REPLACED') throw error;
    }
  };

  connect();
  return {
    ready,
    play,
    stop,
    detach,
    close,
  };
};
