import { transportApi } from './api';
import { createReceivePeer, waitForIceGathering } from './webrtc';

const DISCONNECTED_RECOVERY_MS = 5000;
const retainedCameraWebRtcSessions = new Map();

const closeCameraWebRtcSession = (session, error = null) => {
  if (!session || session.closed) return;
  session.closed = true;
  if (session.closeTimer !== null) {
    window.clearTimeout(session.closeTimer);
    session.closeTimer = null;
  }
  if (session.disconnectedTimer !== null) {
    window.clearTimeout(session.disconnectedTimer);
    session.disconnectedTimer = null;
  }
  if (session.peer) session.peer.close();
  session.stream.getTracks().forEach((track) => track.stop());
  if (session.videoElement?.srcObject === session.stream) {
    session.videoElement.srcObject = null;
  }
  if (session.sessionId) {
    transportApi.stopCameraWebRtc(session.cameraId, session.sessionId).catch(() => {});
  }
  if (retainedCameraWebRtcSessions.get(session.cameraId) === session) {
    retainedCameraWebRtcSessions.delete(session.cameraId);
  }
  const failureHandler = session.onFailure;
  session.videoElement = null;
  session.onFailure = null;
  session.onNegotiated = null;
  if (error && failureHandler) failureHandler(error);
};

const createCameraWebRtcSession = ({ cameraId, audio }) => {
  const session = {
    cameraId,
    audio,
    peer: null,
    stream: new MediaStream(),
    sessionId: null,
    videoElement: null,
    attachmentId: null,
    closeTimer: null,
    disconnectedTimer: null,
    closed: false,
    negotiated: false,
    onFailure: null,
    onNegotiated: null,
    ready: null,
  };
  retainedCameraWebRtcSessions.set(cameraId, session);

  session.ready = (async () => {
    const peer = await createReceivePeer({ audio });
    if (session.closed) {
      peer.close();
      return;
    }
    session.peer = peer;

    peer.ontrack = (event) => {
      if (session.closed) {
        event.track.stop();
        return;
      }
      if (!session.stream.getTracks().some((track) => track.id === event.track.id)) {
        session.stream.addTrack(event.track);
      }
      if (session.videoElement) {
        session.videoElement.srcObject = session.stream;
        session.videoElement.play().catch(() => {});
      }
    };
    peer.onconnectionstatechange = () => {
      if (peer.connectionState === 'failed') {
        closeCameraWebRtcSession(session, new Error('Peer connection failed'));
        return;
      }
      if (peer.connectionState === 'disconnected') {
        if (session.disconnectedTimer === null) {
          session.disconnectedTimer = window.setTimeout(() => {
            session.disconnectedTimer = null;
            if (!session.closed && peer.connectionState === 'disconnected') {
              closeCameraWebRtcSession(
                session,
                new Error('Peer connection remained disconnected'),
              );
            }
          }, DISCONNECTED_RECOVERY_MS);
        }
        return;
      }
      if (session.disconnectedTimer !== null) {
        window.clearTimeout(session.disconnectedTimer);
        session.disconnectedTimer = null;
      }
    };
    peer.oniceconnectionstatechange = () => {
      if (peer.iceConnectionState === 'failed') {
        closeCameraWebRtcSession(session, new Error('ICE connection failed'));
      }
    };

    const offer = await peer.createOffer();
    const iceStartedAt = performance.now();
    await peer.setLocalDescription(offer);
    const iceGathering = await waitForIceGathering(peer, 5000, iceStartedAt);
    const response = await transportApi.startCameraWebRtc(
      cameraId,
      peer.localDescription.sdp,
      iceGathering,
    );
    session.sessionId = response.sessionId;
    if (session.closed) {
      transportApi.stopCameraWebRtc(cameraId, session.sessionId).catch(() => {});
      session.sessionId = null;
      return;
    }
    await peer.setRemoteDescription({ type: 'answer', sdp: response.answerSdp });
    session.negotiated = true;
    if (session.onNegotiated) session.onNegotiated();
  })().catch((error) => {
    closeCameraWebRtcSession(session, error);
    throw error;
  });

  return session;
};

export const resetCameraWebRtcSession = (cameraId) => {
  closeCameraWebRtcSession(retainedCameraWebRtcSessions.get(String(cameraId)));
};

export const connectCameraWebRtc = async ({
  cameraId,
  audio,
  videoElement,
  onFailure,
  onCloseReady,
  onNegotiated,
  retentionMs = 0,
}) => {
  const normalizedCameraId = String(cameraId);
  const normalizedAudio = Boolean(audio);
  let session = retainedCameraWebRtcSessions.get(normalizedCameraId);
  if (
    session
    && (session.closed || session.audio !== normalizedAudio)
  ) {
    closeCameraWebRtcSession(session);
    session = null;
  }
  if (!session) {
    session = createCameraWebRtcSession({
      cameraId: normalizedCameraId,
      audio: normalizedAudio,
    });
  }

  if (session.closeTimer !== null) {
    window.clearTimeout(session.closeTimer);
    session.closeTimer = null;
  }
  const attachmentId = Symbol(normalizedCameraId);
  session.attachmentId = attachmentId;
  session.videoElement = videoElement;
  session.onFailure = onFailure || null;
  session.onNegotiated = onNegotiated || null;
  if (session.stream.getTracks().length > 0) {
    videoElement.srcObject = session.stream;
    videoElement.play().catch(() => {});
  }
  if (session.negotiated && session.onNegotiated) session.onNegotiated();

  const release = () => {
    if (session.closed || session.attachmentId !== attachmentId) return;
    if (videoElement.srcObject === session.stream) videoElement.srcObject = null;
    session.videoElement = null;
    session.onFailure = null;
    session.onNegotiated = null;
    session.attachmentId = null;
    if (retentionMs > 0) {
      session.closeTimer = window.setTimeout(() => {
        session.closeTimer = null;
        closeCameraWebRtcSession(session);
      }, retentionMs);
    } else {
      closeCameraWebRtcSession(session);
    }
  };
  if (onCloseReady) onCloseReady(release);

  await session.ready;
  return release;
};

const RECONNECT_DELAY_MS = 3000;

/**
 * Connect a camera's fMP4-over-WebSocket stream to a <video> element via
 * the MediaSource Extensions API.
 *
 * The backend sends a text frame first containing the MIME/codec string
 * (e.g. `mime:video/mp4; codecs="avc1.42E01F, mp4a.40.2"`), then binary
 * fMP4 data starting with the initialization segment (ftyp + moov).
 *
 * Returns a cleanup function that tears down the connection.
 */
export const connectCameraWsMse = ({ cameraId, videoElement, onUnsupported }) => {
  if (typeof MediaSource === 'undefined') {
    if (onUnsupported) onUnsupported();
    return () => {};
  }

  let closed = false;
  let socket = null;
  let mediaSource = null;
  let sourceBuffer = null;
  let pendingChunks = [];
  let mimeType = null;
  let objectUrl = null;
  let reconnectTimer = null;

  const cleanup = () => {
    closed = true;
    if (reconnectTimer !== null) {
      clearTimeout(reconnectTimer);
      reconnectTimer = null;
    }
    if (socket) {
      socket.onclose = null;
      socket.close();
      socket = null;
    }
    if (mediaSource && mediaSource.readyState === 'open') {
      try { mediaSource.endOfStream(); } catch (_) {}
    }
    if (objectUrl) {
      URL.revokeObjectURL(objectUrl);
      objectUrl = null;
    }
    videoElement.src = '';
    sourceBuffer = null;
    mediaSource = null;
    pendingChunks = [];
  };

  const flushPending = () => {
    if (!sourceBuffer || sourceBuffer.updating || pendingChunks.length === 0) return;
    if (!mediaSource || mediaSource.readyState !== 'open') return;
    const chunk = pendingChunks.shift();
    try {
      sourceBuffer.appendBuffer(chunk);
      // Kick playback on the first successful append
      if (videoElement.paused) videoElement.play().catch(() => {});
    } catch (err) {
      // QuotaExceededError: evict buffered data and retry
      if (err.name === 'QuotaExceededError' && sourceBuffer.buffered.length > 0) {
        const start = sourceBuffer.buffered.start(0);
        const end = Math.max(start, sourceBuffer.buffered.end(0) - 5);
        try {
          sourceBuffer.remove(start, end);
        } catch (_) {}
      }
    }
  };

  const connect = () => {
    if (closed) return;

    let sourceOpenFired = false;

    // Called whenever either condition becomes true (sourceopen OR mime received).
    // Both must be satisfied before we can create the SourceBuffer.
    const trySetupSourceBuffer = () => {
      if (sourceBuffer || closed || !sourceOpenFired || !mimeType) return;
      if (!mediaSource || mediaSource.readyState !== 'open') return;

      let mime = mimeType;
      if (!MediaSource.isTypeSupported(mime)) {
        const videoOnly = mime.replace(/, mp4a\.\d+\.\d+/g, '');
        if (!MediaSource.isTypeSupported(videoOnly)) {
          console.warn('WS-fMP4: codec unsupported:', mime);
          if (onUnsupported) onUnsupported();
          return;
        }
        mime = videoOnly;
      }

      try {
        sourceBuffer = mediaSource.addSourceBuffer(mime);
        sourceBuffer.mode = 'sequence';
        sourceBuffer.addEventListener('updateend', flushPending);
        flushPending();
      } catch (err) {
        console.warn('WS-fMP4: failed to add SourceBuffer:', err);
        if (onUnsupported) onUnsupported();
      }
    };

    mediaSource = new MediaSource();
    objectUrl = URL.createObjectURL(mediaSource);
    videoElement.src = objectUrl;

    mediaSource.addEventListener('sourceopen', () => {
      sourceOpenFired = true;
      trySetupSourceBuffer();
    });

    socket = new WebSocket(transportApi.getCameraFmp4WebSocketUrl(cameraId));
    socket.binaryType = 'arraybuffer';

    socket.onmessage = (event) => {
      if (closed) return;
      if (typeof event.data === 'string') {
        // First text frame carries the MIME type sent by the server
        if (event.data.startsWith('mime:')) {
          mimeType = event.data.slice(5).trim();
          trySetupSourceBuffer();
        }
        return;
      }
      // Binary fMP4 data — buffer regardless of whether SourceBuffer is ready yet
      pendingChunks.push(new Uint8Array(event.data));
      flushPending();
    };

    socket.onclose = () => {
      if (closed) return;
      // Attempt reconnection after a short delay
      reconnectTimer = setTimeout(() => {
        reconnectTimer = null;
        if (!closed) {
          if (mediaSource && mediaSource.readyState === 'open') {
            try { mediaSource.endOfStream(); } catch (_) {}
          }
          URL.revokeObjectURL(objectUrl);
          objectUrl = null;
          sourceBuffer = null;
          mediaSource = null;
          pendingChunks = [];
          connect();
        }
      }, RECONNECT_DELAY_MS);
    };

    socket.onerror = () => {
      if (!closed) socket.close();
    };
  };

  connect();
  return cleanup;
};
