import React, { useEffect, useMemo, useState } from 'react';
import { KeyRound, LogOut, Monitor, Moon, Server, Sun, Wifi } from 'lucide-react';
import { toast } from 'react-hot-toast';

import { api } from '../../api';
import { API_ENDPOINT_MODES, isLocalApiEndpoint } from '../../connection';

const isLocalBackend = (baseUrl, mode) => {
  return isLocalApiEndpoint({ baseUrl, mode });
};

function Admin({
  apiEndpoint,
  customEndpointInput,
  customEndpointError,
  onApiEndpointModeChange,
  onCustomEndpointInputChange,
  onCustomEndpointBlur,
  onCustomEndpointApply,
  onLogout,
  minimalMode,
  minimalModeForced = false,
  onMinimalModeChange,
  theme = 'default',
  onThemeChange,
  onReloadNetworkEndpoints,
}) {
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordSaving, setPasswordSaving] = useState(false);
  const [networkReloading, setNetworkReloading] = useState(false);
  const [passwordError, setPasswordError] = useState('');
  const [wifiStatus, setWifiStatus] = useState(null);
  const [wifiNetworks, setWifiNetworks] = useState([]);
  const [wifiSsid, setWifiSsid] = useState('');
  const [wifiPassword, setWifiPassword] = useState('');
  const [wifiBusy, setWifiBusy] = useState(false);
  const [wifiError, setWifiError] = useState('');
  const passwordChangeEnabled = useMemo(
    () => isLocalBackend(apiEndpoint.baseUrl, apiEndpoint.mode),
    [apiEndpoint.baseUrl, apiEndpoint.mode]
  );
  const windowHost = useMemo(() => {
    try {
      return window.location?.hostname || 'Unavailable';
    } catch (error) {
      return 'Unavailable';
    }
  }, []);

  useEffect(() => {
    let active = true;
    const loadStatus = async () => {
      try {
        const response = await api.getWifiStatus();
        if (active) setWifiStatus(response.data);
      } catch (_) {
        if (active) setWifiStatus(null);
      }
    };
    loadStatus();
    const timer = window.setInterval(loadStatus, 5000);
    return () => {
      active = false;
      window.clearInterval(timer);
    };
  }, []);

  const handleWifiScan = async () => {
    setWifiBusy(true);
    setWifiError('');
    try {
      const response = await api.getWifiNetworks();
      const networks = response?.data?.networks || [];
      setWifiNetworks(networks);
      if (!wifiSsid && networks.length) setWifiSsid(networks[0].ssid);
    } catch (error) {
      setWifiError(error?.response?.data?.detail || 'Could not scan Wi-Fi networks.');
    } finally {
      setWifiBusy(false);
    }
  };

  const handleWifiConnect = async (event) => {
    event.preventDefault();
    if (!wifiSsid.trim()) {
      setWifiError('Select or enter an SSID.');
      return;
    }
    setWifiBusy(true);
    setWifiError('');
    try {
      await api.connectWifi(wifiSsid.trim(), wifiPassword);
      toast.success('Wi-Fi connection started. The hotspot may disconnect.');
      setWifiStatus(previous => ({ ...previous, connecting: true, message: `Connecting to ${wifiSsid.trim()}…` }));
    } catch (error) {
      setWifiError(error?.response?.data?.detail || 'Could not start Wi-Fi connection.');
    } finally {
      setWifiBusy(false);
    }
  };

  const handlePasswordSubmit = async (event) => {
    event.preventDefault();
    setPasswordError('');

    if (!passwordChangeEnabled) {
      setPasswordError('Password changes are only available from the local backend.');
      return;
    }
    if (!currentPassword || !newPassword || !confirmPassword) {
      setPasswordError('Fill in all password fields.');
      return;
    }
    if (newPassword !== confirmPassword) {
      setPasswordError('New passwords do not match.');
      return;
    }

    setPasswordSaving(true);
    try {
      const response = await api.changePassword(currentPassword, newPassword);
      const token = response?.data?.access_token;
      if (token) {
        api.setAccessToken(token);
      }
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
      toast.success('Password updated');
    } catch (error) {
      setPasswordError(error?.response?.data?.detail || 'Failed to update password.');
    } finally {
      setPasswordSaving(false);
    }
  };

  const handleReloadNetworkEndpoints = async () => {
    if (!onReloadNetworkEndpoints || networkReloading) {
      return;
    }

    setNetworkReloading(true);
    try {
      await onReloadNetworkEndpoints();
      toast.success('Network endpoints reloaded');
    } catch (error) {
      toast.error(error?.response?.data?.detail || 'Failed to reload network endpoints.');
    } finally {
      setNetworkReloading(false);
    }
  };

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Admin</h1>
        <p className="page-subtitle">Backend connection and session controls</p>
      </div>

      <div className="system-info-grid admin-grid">
        <div className="info-card admin-wifi-card">
          <div className="info-title admin-title">
            <Wifi size={20} />
            Wi-Fi setup
          </div>
          <div className={`admin-wifi-status admin-wifi-status--${wifiStatus?.level || 'info'}`}>
            {wifiStatus?.message || 'Wi-Fi service status unavailable.'}
          </div>
          {wifiStatus?.hotspot_active && (
            <div className="admin-wifi-hotspot">
              Hotspot: <strong>{wifiStatus.hotspot_ssid}</strong> · Password: <strong>{wifiStatus.hotspot_password}</strong>
            </div>
          )}
          <form className="admin-password-form" onSubmit={handleWifiConnect}>
            <div className="admin-wifi-actions">
              <button type="button" className="btn btn-secondary" onClick={handleWifiScan} disabled={wifiBusy || wifiStatus?.connecting}>
                {wifiBusy ? 'Scanning…' : 'Scan networks'}
              </button>
            </div>
            <label className="form-label" htmlFor="wifi-ssid">Network</label>
            <input
              id="wifi-ssid"
              className="api-endpoint-input"
              list="wifi-network-list"
              value={wifiSsid}
              onChange={(event) => setWifiSsid(event.target.value)}
              placeholder="Select or enter an SSID"
              disabled={wifiStatus?.connecting}
            />
            <datalist id="wifi-network-list">
              {wifiNetworks.map(network => (
                <option key={network.ssid} value={network.ssid}>{network.signal}% · {network.security}</option>
              ))}
            </datalist>
            <label className="form-label" htmlFor="wifi-password">Password</label>
            <input
              id="wifi-password"
              className="api-endpoint-input"
              type="password"
              value={wifiPassword}
              onChange={(event) => setWifiPassword(event.target.value)}
              autoComplete="new-password"
              placeholder="Leave blank for an open network"
              disabled={wifiStatus?.connecting}
            />
            {wifiError && <span className="api-endpoint-error">{wifiError}</span>}
            <button type="submit" className="btn btn-primary admin-password-submit" disabled={wifiBusy || wifiStatus?.connecting || wifiStatus?.available === false}>
              <Wifi size={18} />
              {wifiStatus?.connecting ? 'Connecting…' : 'Connect'}
            </button>
          </form>
        </div>
        <div className="info-card">
          <div className="info-title admin-title">
            <Server size={20} />
            Backend
          </div>
          <div className="api-endpoint-control api-endpoint-control--admin">
            <label className="api-endpoint-label" htmlFor="api-endpoint-mode">
              Connection
            </label>
            <button
              type="button"
              className="btn btn-secondary admin-network-reload"
              onClick={handleReloadNetworkEndpoints}
              disabled={networkReloading}
            >
              {networkReloading ? 'Reloading...' : 'Reload'}
            </button>
            <select
              id="api-endpoint-mode"
              className="api-endpoint-select"
              value={apiEndpoint.mode}
              onChange={onApiEndpointModeChange}
            >
              {apiEndpoint.options.map(option => (
                <option key={option.value} value={option.value} disabled={!option.baseUrl && option.value !== API_ENDPOINT_MODES.CUSTOM}>
                  {option.baseUrl ? `${option.label} - ${option.baseUrl}` : option.label}
                </option>
              ))}
            </select>
            {apiEndpoint.mode === API_ENDPOINT_MODES.CUSTOM && (
              <div className="api-endpoint-custom">
                <input
                  type="text"
                  className="api-endpoint-input"
                  value={customEndpointInput}
                  onChange={onCustomEndpointInputChange}
                  onBlur={onCustomEndpointBlur}
                  placeholder="192.168.1.10:9001"
                  autoComplete="off"
                  spellCheck="false"
                />
                <button
                  type="button"
                  className="api-endpoint-apply"
                  onClick={onCustomEndpointApply}
                >
                  Apply
                </button>
              </div>
            )}
            <span className="api-endpoint-current">
              Window IP: {windowHost}
            </span>
            <span className="api-endpoint-current">{apiEndpoint.baseUrl}</span>
            {customEndpointError && (
              <span className="api-endpoint-error">{customEndpointError}</span>
            )}
          </div>
          <div className="admin-card-section">
            <div className="admin-section-title">
              <Monitor size={17} />
              Interface
            </div>
            <div className="admin-toggle-row">
              <div>
                <div className="admin-toggle-title">Minimal mode</div>
                <div className="admin-toggle-subtitle">
                  {minimalModeForced
                    ? 'Required while using a non-local API endpoint.'
                    : 'Show only Event, Camera, and Admin pages.'}
                </div>
              </div>
              <label className="admin-switch">
                <input
                  type="checkbox"
                  checked={minimalMode}
                  disabled={minimalModeForced}
                  onChange={(event) => onMinimalModeChange(event.target.checked)}
                />
                <span className="admin-switch-track" />
              </label>
            </div>
            <div className="admin-theme-row">
              <div>
                <div className="admin-toggle-title">Theme</div>
                <div className="admin-toggle-subtitle">Choose the default or dark interface.</div>
              </div>
              <div className="admin-theme-control" role="radiogroup" aria-label="Theme">
                <button
                  type="button"
                  className={`admin-theme-option${theme !== 'dark' ? ' active' : ''}`}
                  onClick={() => onThemeChange?.('default')}
                  aria-pressed={theme !== 'dark'}
                >
                  <Sun size={14} />
                  Default
                </button>
                <button
                  type="button"
                  className={`admin-theme-option${theme === 'dark' ? ' active' : ''}`}
                  onClick={() => onThemeChange?.('dark')}
                  aria-pressed={theme === 'dark'}
                >
                  <Moon size={14} />
                  Dark
                </button>
              </div>
            </div>
          </div>
        </div>

        <div className="info-card">
          <div className="info-title admin-title">
            <LogOut size={20} />
            Session
          </div>
          <button
            type="button"
            className="btn btn-secondary admin-logout"
            onClick={onLogout}
          >
            <LogOut size={18} />
            Logout
          </button>
          <div className="admin-card-section">
            <div className="admin-section-title">
              <KeyRound size={17} />
              Change password
            </div>
            <form className="admin-password-form" onSubmit={handlePasswordSubmit}>
            <label className="form-label" htmlFor="current-password">Current password</label>
            <input
              id="current-password"
              className="api-endpoint-input"
              type="password"
              value={currentPassword}
              onChange={(event) => setCurrentPassword(event.target.value)}
              autoComplete="current-password"
              disabled={!passwordChangeEnabled || passwordSaving}
            />

            <label className="form-label" htmlFor="new-password">New password</label>
            <input
              id="new-password"
              className="api-endpoint-input"
              type="password"
              value={newPassword}
              onChange={(event) => setNewPassword(event.target.value)}
              autoComplete="new-password"
              disabled={!passwordChangeEnabled || passwordSaving}
            />

            <label className="form-label" htmlFor="confirm-password">Confirm password</label>
            <input
              id="confirm-password"
              className="api-endpoint-input"
              type="password"
              value={confirmPassword}
              onChange={(event) => setConfirmPassword(event.target.value)}
              autoComplete="new-password"
              disabled={!passwordChangeEnabled || passwordSaving}
            />

            {!passwordChangeEnabled && (
              <span className="api-endpoint-error">Switch to Local backend to change the password.</span>
            )}
            {passwordError && (
              <span className="api-endpoint-error">{passwordError}</span>
            )}

            <button
              type="submit"
              className="btn btn-primary admin-password-submit"
              disabled={!passwordChangeEnabled || passwordSaving}
            >
              <KeyRound size={18} />
              {passwordSaving ? 'Saving...' : 'Change password'}
            </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Admin;
