import { transportApi } from './api';
import { createReceivePeer, waitForIceGathering } from './webrtc';

export const connectRecordingWebRtc = async ({
  recordingId,
  mode,
  overlay,
  videoElement,
  onFailure,
  onCloseReady,
}) => {
  const peer = await createReceivePeer({ audio: true, turnOnly: mode === 'webrtc-turn' });
  const stream = new MediaStream();
  let sessionId = null;
  let closed = false;

  const close = () => {
    if (closed) return;
    closed = true;
    peer.close();
    stream.getTracks().forEach((track) => track.stop());
    if (videoElement.srcObject === stream) videoElement.srcObject = null;
    if (sessionId) transportApi.stopRecordingWebRtc(recordingId, sessionId).catch(() => {});
  };
  if (onCloseReady) onCloseReady(close);

  peer.ontrack = (event) => {
    if (closed) {
      event.track.stop();
      return;
    }
    if (!stream.getTracks().some((track) => track.id === event.track.id)) {
      stream.addTrack(event.track);
    }
    videoElement.srcObject = stream;
    videoElement.play().catch(() => {});
  };
  peer.onconnectionstatechange = () => {
    if (closed || !['failed', 'disconnected'].includes(peer.connectionState)) return;
    const error = new Error(`WebRTC ${peer.connectionState}`);
    close();
    if (onFailure) onFailure(error);
  };

  try {
    const offer = await peer.createOffer();
    await peer.setLocalDescription(offer);
    await waitForIceGathering(peer);
    const response = await transportApi.startRecordingWebRtc(
      recordingId,
      peer.localDescription.sdp,
      overlay,
    );
    sessionId = response.sessionId;
    if (closed) {
      transportApi.stopRecordingWebRtc(recordingId, sessionId).catch(() => {});
      return close;
    }
    await peer.setRemoteDescription({ type: 'answer', sdp: response.answerSdp });
    return close;
  } catch (error) {
    close();
    throw error;
  }
};
