import React, { useEffect, useState, useCallback } from 'react';
import {
  LineChart, Line, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer,
  CartesianGrid, ReferenceLine,
} from 'recharts';
import api from '../../api';
import { formatChartTime, formatWithServerTz } from '../EventView/EventViewUtils';

const CHART_HEIGHT = 196;

const SERIES = [
  { key: 'cpu',      label: 'System CPU %',  color: '#e6194b', dash: undefined },
  { key: 'mem',      label: 'System RAM %',  color: '#4363d8', dash: undefined },
  { key: 'proc_cpu', label: 'Server CPU %',  color: '#f58231', dash: '5 5' },
  { key: 'proc_mem', label: 'Server RAM %',  color: '#911eb4', dash: '5 5' },
  { key: 'ai_cpu',   label: 'AI CPU %',      color: '#3cb44b', dash: '3 3' },
  { key: 'ai_mem',   label: 'AI RAM %',      color: '#42d4f4', dash: '3 3' },
];

const formatTime = (ts, timezoneOffset) => {
  if (!ts) return '';
  return formatChartTime(ts, timezoneOffset);
};

const formatTimeFull = (ts, timezoneOffset) => {
  if (!ts) return '';
  return formatWithServerTz(ts, timezoneOffset, 'time-full');
};

const CustomTooltip = ({ active, payload, label, timezoneOffset }) => {
  if (!active || !payload || !payload.length) return null;
  return (
    <div style={{ background: '#fff', border: '1px solid #ddd', borderRadius: 6, padding: '8px 12px', fontSize: 12, boxShadow: '0 2px 8px rgba(0,0,0,0.15)' }}>
      <div style={{ color: '#666', marginBottom: 4 }}>{formatTimeFull(label, timezoneOffset)}</div>
      {payload.map((entry, i) => (
        <div key={i} style={{ color: entry.color, marginBottom: 2 }}>
          {entry.name}: {Number(entry.value).toFixed(1)}%
        </div>
      ))}
    </div>
  );
};

const ResourceUsageChart = ({ serverTimezone }) => {
  const [chartData, setChartData] = useState([]);
  const [visible, setVisible] = useState({ cpu: false, mem: false, proc_cpu: true, proc_mem: true, ai_cpu: true, ai_mem: true });

  const fetchHistory = useCallback(async () => {
    try {
      const res = await api.getResourceHistory();
      setChartData(res.data || []);
    } catch {
      // stay empty
    }
  }, []);

  useEffect(() => {
    fetchHistory();
    const id = setInterval(fetchHistory, 60000);
    return () => clearInterval(id);
  }, [fetchHistory]);

  const toggle = (key) => setVisible(prev => ({ ...prev, [key]: !prev[key] }));

  // Wrapper functions to pass timezone to formatters
  const formatTimeWithTz = (ts) => formatTime(ts, serverTimezone?.offset);
  const customTooltipWithTz = (props) => <CustomTooltip {...props} timezoneOffset={serverTimezone?.offset} />;

  const hasData = chartData.length > 0;

  return (
    <div>
      {/* Controls */}
      <div style={{ display: 'flex', gap: 12, marginBottom: 12, flexWrap: 'wrap', alignItems: 'center' }}>
        {SERIES.map(s => (
          <label key={s.key} style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 13, color: '#546e7a', cursor: 'pointer' }}>
            <input type="checkbox" checked={!!visible[s.key]} onChange={() => toggle(s.key)} />
            <span style={{ color: s.color, fontWeight: 600 }}>{s.label}</span>
          </label>
        ))}
      </div>

      {/* Chart */}
      {hasData ? (
        <ResponsiveContainer width="100%" height={CHART_HEIGHT}>
          <LineChart data={chartData} margin={{ top: 5, right: 20, left: 10, bottom: 5 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
            <XAxis
              dataKey="ts" tickFormatter={formatTimeWithTz} stroke="#999"
              tick={{ fontSize: 11, fill: '#666' }} interval="preserveStartEnd"
            />
            <YAxis
              stroke="#999" tick={{ fontSize: 11, fill: '#666' }}
              domain={[0, 100]}
              label={{ value: '%', angle: -90, position: 'insideLeft', style: { fill: '#666', fontSize: 12 } }}
            />
            <Tooltip content={customTooltipWithTz} />
            <Legend wrapperStyle={{ fontSize: 12 }} formatter={(value) => <span style={{ color: '#546e7a' }}>{value}</span>} />
            <ReferenceLine y={80} stroke="#ff7043" strokeDasharray="6 3" label={{ value: '80%', fill: '#ff7043', fontSize: 10 }} />
            {SERIES.filter(s => visible[s.key]).map(s => (
              <Line
                key={s.key} type="monotone" dataKey={s.key} name={s.label}
                stroke={s.color} strokeWidth={1.5}
                strokeDasharray={s.dash}
                dot={false} isAnimationActive={false}
              />
            ))}
          </LineChart>
        </ResponsiveContainer>
      ) : (
        <div style={{ color: '#999', textAlign: 'center', padding: '40px 0', fontSize: 14 }}>
          No resource data yet. Data will appear after ~30 seconds of uptime.
        </div>
      )}
      <div style={{ fontSize: 11, color: '#aaa', marginTop: 6, textAlign: 'right' }}>
        Sample rate: 30 s &nbsp;·&nbsp; Metrics averages window: 30 s
      </div>
    </div>
  );
};

export default ResourceUsageChart;
