import React, { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Trash2, Play, Square, Power, PowerOff, Mic, MicOff, MapPin, LayoutGrid } from 'lucide-react';
import { toast } from 'react-hot-toast';
import { api } from '../../api';
import { COMPACT_BUTTON_STYLE } from './CameraForm';
import {
  AUDIO_TOGGLE_STYLE,
  CameraAudioPanel, CameraVideoPanel,
} from './CameraViewPanels';
import './CameraList.css';

// Compact icon-only style for camera card control buttons
const ICON_BTN = { padding: '5px 6px', fontSize: '12px', lineHeight: 1 };

// ---------------------------------------------------------------------------
// Module-level components — defined OUTSIDE CameraList so React never sees a
// new component type on re-renders, which would unmount/remount every card
// and tear down active WebRTC/HLS/WS streams unnecessarily.
// ---------------------------------------------------------------------------

const CameraCard = ({
  camera,
  streamMode,
  activeStreamModes,
  isStarting,
  isStopping,
  recordingLoadingState,
  showPowerControls,
  globalCompactMode,
  minimalMode,
  supportEnabled,
  onStart,
  onStop,
  onStartRecording,
  onStopRecording,
  onDelete,
  onSupportToggle,
  onAudioToggle,
}) => {
  const navigate = useNavigate();
  const displayStatus = camera.is_recording ? 'recording' : camera.status;
  const [activeStreamMode, setActiveStreamMode] = useState(streamMode);
  return (
    <div className="camera-card">
      <div className="camera-header" style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
        <div className="camera-title" style={{ flexShrink: 0 }}>{camera.name}</div>
        <div className="camera-info" style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap', flex: 1 }}>
          {displayStatus === 'recording' || displayStatus === 'offline' ? (
            <span
              className={`camera-status-dot camera-status-dot-${displayStatus}`}
              title={displayStatus}
              aria-label={displayStatus}
            />
          ) : (
            <span className={`status status-${displayStatus}`}>{displayStatus}</span>
          )}
          <span className="camera-meta">
            {camera.resolution || 'N/A'}
          </span>
          <span className="camera-meta">
            {camera.fps ? `${camera.fps} FPS` : 'FPS N/A'}
          </span>
          <span className="camera-meta">
            {camera.camera_type || 'N/A'}
          </span>
          <span className="camera-meta">
            {camera.audio_enabled
              ? `${camera.audio_sample_rate || 'N/A'} Hz`
              : 'No audio'}
          </span>
          <span className="camera-meta camera-meta-mode">
            {formatStreamMode(activeStreamMode)}
          </span>
        </div>
      </div>

      <div className="camera-video" style={{ display: 'flex', gap: '16px', flexWrap: 'wrap' }}>
        <div className="camera-column primary-column">
          <div className="camera-frame">
            <CameraVideoPanel
              camera={camera}
              variant="primary"
              streamMode={streamMode}
              minimalMode={minimalMode}
              activeStreamModes={activeStreamModes}
              onEffectiveStreamModeChange={setActiveStreamMode}
            />
          </div>

          {showPowerControls && (
          <div className="camera-controls-card">
            {displayStatus === 'offline' || displayStatus === 'error' ? (
              <button
                className={`btn btn-success${isStarting ? ' btn-starting' : ''}`}
                onClick={() => onStart(camera.id)}
                disabled={isStarting}
                title="Start camera"
                style={ICON_BTN}
              >
                <Power
                  size={14}
                  style={{ animation: isStarting ? 'btn-spin 1s linear infinite' : 'none' }}
                />
              </button>
            ) : (
              <button
                className={`btn btn-secondary${isStopping ? ' btn-stopping' : ''}`}
                onClick={() => onStop(camera.id)}
                disabled={displayStatus === 'recording' || isStopping}
                title="Stop camera"
                style={ICON_BTN}
              >
                <PowerOff
                  size={14}
                  style={{ animation: isStopping ? 'btn-spin 1s linear infinite' : 'none' }}
                />
              </button>
            )}

            {displayStatus === 'recording' ? (
              <button
                className={`btn btn-danger${recordingLoadingState === 'stopping' ? ' btn-rec-stopping' : ' btn-recording-active'}`}
                onClick={() => onStopRecording(camera.id)}
                disabled={recordingLoadingState === 'stopping'}
                title="Stop recording"
                style={ICON_BTN}
              >
                {recordingLoadingState === 'stopping'
                  ? <Square size={14} style={{ animation: 'btn-spin 1s linear infinite' }} />
                  : <span className="rec-dot" />}
              </button>
            ) : (
              <button
                className={`btn btn-success${recordingLoadingState === 'starting' ? ' btn-rec-starting' : ''}`}
                onClick={() => onStartRecording(camera.id)}
                disabled={displayStatus !== 'online' || recordingLoadingState === 'starting'}
                title={displayStatus !== 'online' ? `Camera must be online to record (current: ${displayStatus})` : 'Start recording'}
                style={{
                  ...ICON_BTN,
                  opacity: displayStatus !== 'online' ? 0.92 : 1,
                  filter: 'none',
                  background: displayStatus !== 'online' ? '#2f5f37' : undefined,
                  borderColor: displayStatus !== 'online' ? '#3d7d48' : undefined,
                  color: displayStatus !== 'online' ? '#e8f5eb' : undefined,
                }}
              >
                <Play
                  size={14}
                  style={{ animation: recordingLoadingState === 'starting' ? 'btn-spin 1s linear infinite' : 'none' }}
                />
              </button>
            )}

            <button
              className="btn btn-secondary"
              onClick={() => navigate(`/zones?camera=${camera.id}`)}
              title="Configure motion zones"
              style={ICON_BTN}
            >
              <MapPin size={14} />
            </button>

            <button
              className="btn btn-danger"
              onClick={() => onDelete(camera.id)}
              title="Delete camera"
              style={ICON_BTN}
            >
              <Trash2 size={14} />
            </button>

            <label
              title="Enable Audio (record + live)"
              style={{
                ...AUDIO_TOGGLE_STYLE,
                background: camera.audio_enabled ? '#1e293b' : '#151a21',
                color: camera.audio_enabled ? '#22c55e' : '#d6deea',
              }}
            >
              <input
                type="checkbox"
                checked={Boolean(camera.audio_enabled)}
                onChange={(e) => onAudioToggle(camera, e.target.checked)}
                style={{ display: 'none' }}
                aria-label="Enable audio"
              />
              {camera.audio_enabled ? <Mic size={14} /> : <MicOff size={14} />}
            </label>

            {streamMode !== 'webrtc' && <CameraAudioPanel camera={camera} />}
          </div>
          )}
        </div>

        {!globalCompactMode && (
        <div className="camera-column support-column">
          <div className="camera-frame">
            <CameraVideoPanel
              camera={camera}
              variant="support"
              streamMode={streamMode}
              minimalMode={minimalMode}
              activeStreamModes={activeStreamModes}
            />
          </div>

          {showPowerControls && (
            <div className="view-controls-card">
              <button
                className="btn btn-outline support-toggle-btn"
                onClick={() => onSupportToggle(camera.id)}
                style={COMPACT_BUTTON_STYLE}
              >
                {supportEnabled ? 'Disable' : 'Enable'}
              </button>
            </div>
          )}
        </div>
        )}
      </div>
    </div>
  );
};

const formatStreamMode = (mode) => {
  const normalized = String(mode || 'mjpeg').toUpperCase();
  return normalized === 'WS' ? 'WebSocket' : normalized;
};

const isLiveCamera = (camera) => ['online', 'recording'].includes(String(camera?.status || '').toLowerCase());

const CameraList = ({
  cameras,
  setCameras,
  streamMode = 'mjpeg',
  activeStreamModes = ['ws', 'webrtc', 'hls', 'mjpeg'],
  minimalMode = false,
}) => {
  const navigate = useNavigate();
  // -----------------------------
  // Page-level state
  // -----------------------------
  // Per-camera UI settings for supporting screen
  const [cameraSettings, setCameraSettings] = useState({}); // { [id]: { supportEnabled: boolean } }



  const [startingCameras, setStartingCameras] = useState({}); // { [camera_id]: boolean }
  const [stoppingCameras, setStoppingCameras] = useState({}); // { [camera_id]: boolean }
  const [recordingLoading, setRecordingLoading] = useState({}); // { [camera_id]: 'starting' | 'stopping' | null }
  const [globalCompactMode, setGlobalCompactMode] = useState(true);
  const [showPowerControls, setShowPowerControls] = useState(false);
  const orderedCameras = useMemo(() => (
    [...cameras].sort((a, b) => {
      const liveDelta = Number(isLiveCamera(b)) - Number(isLiveCamera(a));
      if (liveDelta !== 0) {
        return liveDelta;
      }
      return String(a?.name || '').localeCompare(String(b?.name || ''), undefined, {
        numeric: true,
        sensitivity: 'base',
      });
    })
  ), [cameras]);

  const handleSupportToggle = (cameraId) => {
    setCameraSettings(prev => {
      const cur = prev[cameraId] || { supportEnabled: false };
      return {
        ...prev,
        [cameraId]: { ...cur, supportEnabled: !cur.supportEnabled }
      };
    });
  };

  // Utility to update one camera entry in local list state.
  const patchCameraInState = (cameraId, partial) => {
    setCameras((prev) => prev.map((item) => (item.id === cameraId ? { ...item, ...partial } : item)));
  };

  const handleDeleteCamera = async (cameraId) => {
    if (!window.confirm('Are you sure you want to delete this camera?')) {
      return;
    }
    
    try {
      await api.deleteCamera(cameraId);
      setCameras(prev => prev.filter(c => c.id !== cameraId));
      toast.success('Camera deleted successfully');
    } catch (error) {
      toast.error('Failed to delete camera: ' + (error.response?.data?.detail || error.message));
    }
  };
  
  const handleStartCamera = async (cameraId) => {
    try {
      setStartingCameras(prev => ({ ...prev, [cameraId]: true }));
      await api.startCamera(cameraId);
      // Give background threads time to start before UI shows streams
      await new Promise(resolve => setTimeout(resolve, 750));
      setCameras(prev => prev.map(item => (
        item.id === cameraId
          ? {
              ...item,
              status: item.is_recording ? 'recording' : 'online',
              last_seen: new Date().toISOString(),
            }
          : item
      )));
      toast.success('Camera started');
    } catch (error) {
      console.error('Start camera error:', error);
      toast.error('Failed to start camera: ' + (error.response?.data?.detail || error.message));
    } finally {
      setStartingCameras(prev => ({ ...prev, [cameraId]: false }));
    }
  };

  const handleStopCamera = async (cameraId) => {
    try {
      setStoppingCameras(prev => ({ ...prev, [cameraId]: true }));
      await api.stopCamera(cameraId);
      try { await api.stopCamera(cameraId); } catch {}
      patchCameraInState(cameraId, { status: 'offline' });
      toast.success('Camera stopped');
    } catch (error) {
      console.error('Stop camera error:', error);
      toast.error('Failed to stop camera: ' + (error.response?.data?.detail || error.message));
    } finally {
      setStoppingCameras(prev => ({ ...prev, [cameraId]: false }));
    }
  };

  const handleStartRecording = async (cameraId) => {
    try {
      setRecordingLoading(prev => ({ ...prev, [cameraId]: 'starting' }));
      await api.startRecording(cameraId);
      patchCameraInState(cameraId, { status: 'recording', is_recording: true });
      toast.success('Recording started');
    } catch (error) {
      console.error('Start recording error:', error);
      toast.error('Failed to start recording: ' + (error.response?.data?.detail || error.message));
    } finally {
      setRecordingLoading(prev => ({ ...prev, [cameraId]: null }));
    }
  };

  const handleStopRecording = async (cameraId) => {
    try {
      setRecordingLoading(prev => ({ ...prev, [cameraId]: 'stopping' }));
      await api.stopRecording(cameraId);
      patchCameraInState(cameraId, { status: 'online', is_recording: false, recording_id: null });
      toast.success('Recording stopped');
    } catch (error) {
      console.error('Stop recording error:', error);
      toast.error('Failed to stop recording: ' + (error.response?.data?.detail || error.message));
    } finally {
      setRecordingLoading(prev => ({ ...prev, [cameraId]: null }));
    }
  };

  const handleToggleCameraAudioEnabled = async (camera, enabled) => {
    const updates = { audio_enabled: Boolean(enabled) };

    try {
      const response = await api.updateCamera(camera.id, updates);
      setCameras((prev) => prev.map((item) => (item.id === camera.id ? response.data : item)));
    } catch (error) {
      toast.error('Failed to update audio setting: ' + (error.response?.data?.detail || error.message));
    }
  };

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Cameras</h1>
        <p className="page-subtitle">Manage your cameras and recording settings</p>
      </div>

      <div className="content-section">
        <div className="section-header">
          <h2 className="section-title">Camera List ({cameras.length})</h2>
          <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' }}>
            <div
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '10px',
                padding: '6px 10px',
                border: '1px solid rgba(0, 150, 136, 0.25)',
                borderRadius: '10px',
                background: 'rgba(0, 150, 136, 0.06)',
                fontSize: '12px',
                color: '#004d40',
              }}
            >
              <span style={{ fontWeight: 700 }}>Start/Stop Controls</span>
              <label style={{ display: 'inline-flex', alignItems: 'center', gap: '4px', cursor: 'pointer' }}>
                <input
                  type="radio"
                  name="camera-power-controls"
                  checked={!showPowerControls}
                  onChange={() => setShowPowerControls(false)}
                />
                Hide
              </label>
              <label style={{ display: 'inline-flex', alignItems: 'center', gap: '4px', cursor: 'pointer' }}>
                <input
                  type="radio"
                  name="camera-power-controls"
                  checked={showPowerControls}
                  onChange={() => setShowPowerControls(true)}
                />
                Show
              </label>
            </div>
            <button
              className={`btn ${globalCompactMode ? 'btn-primary' : 'btn-secondary'}`}
              onClick={() => setGlobalCompactMode(prev => !prev)}
              title={globalCompactMode ? 'Show full view with support cameras' : 'Compact grid — hide support views'}
              style={COMPACT_BUTTON_STYLE}
            >
              <LayoutGrid size={14} />
              {globalCompactMode ? 'Full View' : 'Compact'}
            </button>
          </div>
        </div>

        <div className={`camera-grid${globalCompactMode ? ' compact-grid' : ''}`}>
          {orderedCameras.map((camera) => (
            <CameraCard
              key={camera.id}
              camera={camera}
              streamMode={streamMode}
              activeStreamModes={activeStreamModes}
              isStarting={Boolean(startingCameras[camera.id])}
              isStopping={Boolean(stoppingCameras[camera.id])}
              recordingLoadingState={recordingLoading[camera.id] || null}
              showPowerControls={showPowerControls}
              globalCompactMode={globalCompactMode}
              minimalMode={minimalMode}
              supportEnabled={cameraSettings[camera.id]?.supportEnabled ?? false}
              onStart={handleStartCamera}
              onStop={handleStopCamera}
              onStartRecording={handleStartRecording}
              onStopRecording={handleStopRecording}
              onDelete={handleDeleteCamera}
              onSupportToggle={handleSupportToggle}
              onAudioToggle={handleToggleCameraAudioEnabled}
            />
          ))}

          {cameras.length === 0 && (
            <div className="camera-card">
              <div className="camera-video">
                <div className="camera-placeholder">
                  <p>No cameras configured</p>
                  <button
                    className="btn btn-primary"
                    onClick={() => navigate('/settings')}
                    style={COMPACT_BUTTON_STYLE}
                  >
                    Open Settings
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

    </div>
  );
};

export default CameraList;
