import React, { useCallback, useMemo, useState, useEffect, useRef } from 'react';
import { BrowserRouter, HashRouter, Routes, Route, NavLink } from 'react-router-dom';
import { Toaster, toast } from 'react-hot-toast';
import { Camera, Settings, BarChart3, Download, Monitor, MapPin, Users, Server, Network as NetworkIcon } from 'lucide-react';

import Dashboard from './components/Dashboard/Dashboard';
import CameraList from './components/CameraList/CameraList';
import RecordingList from './components/RecordingList/RecordingList';
import EventView from './components/EventView/EventView';
import SystemSettings from './components/SystemSettings/SystemSettings';
import Admin from './components/Admin/Admin';
import LoginScreen from './components/LoginScreen/LoginScreen';
import ZoneStudio from './components/ZoneStudio/ZoneStudio';
import PersonGallery from './components/PersonGallery/PersonGallery';
import Network from './components/Network/Network';
import { api } from './api';
import {
  API_ENDPOINT_MODES,
  getApiEndpointSettings,
  getMinimalModeState,
  getStoredMinimalMode,
  normalizeApiBaseUrl,
  normalizeLocalDeviceId,
  setApiEndpointMode,
  setCustomApiBaseUrl,
  setDiscoveredApiEndpoints,
  setLocalDeviceId,
  setStoredMinimalMode,
  setupStreamingFeatures,
} from './connection';
import { connectApplicationDataChannel } from './transports/data_channel';
import {
  ENDPOINT_PRIORITY_CHECK_INTERVAL_MS,
  selectPreferredApiEndpoint,
} from './endpointManager';

import './App.css';

const THEME_STORAGE_KEY = 'nvr_theme';
const THEMES = {
  DEFAULT: 'default',
  DARK: 'dark',
};

const RECORDINGS_PAGE_SIZE = 300;
const EVENT_RECORDINGS_PAGE_SIZE = 50;
const EMPTY_RECORDING_PAGINATION = {
  cameraId: null,
  date: null,
  loaded: 0,
  total: 0,
  hasMore: false,
  loading: false,
  initialized: false,
  error: '',
};

const getStoredTheme = () => {
  if (typeof window === 'undefined') return THEMES.DEFAULT;
  return window.localStorage?.getItem(THEME_STORAGE_KEY) === THEMES.DARK
    ? THEMES.DARK
    : THEMES.DEFAULT;
};

const isRunningAsInstalledApp = () => (
  typeof window !== 'undefined'
  && (
    window.matchMedia?.('(display-mode: standalone)').matches
    || window.navigator?.standalone === true
  )
);

const RouterComponent =
  typeof window !== 'undefined' && window.location?.protocol === 'file:'
    ? HashRouter
    : BrowserRouter;

const getRecordingMetadata = (recording) => {
  const metadata = recording?.metadata;
  if (!metadata) return {};
  if (typeof metadata === 'string') {
    try {
      return JSON.parse(metadata) || {};
    } catch (_) {
      return {};
    }
  }
  return typeof metadata === 'object' ? metadata : {};
};

const getRecordingTextLog = (recording) => {
  const metadata = getRecordingMetadata(recording);
  return String(metadata.text_log || metadata.event_log || '').trim();
};

const getRecordingDateKey = (recording) => {
  const timestamp = recording?.start_time || recording?.started_at || recording?.created_at;
  return timestamp ? String(timestamp).slice(0, 10) : '';
};

const showRecordingNotification = (recording) => {
  const textLog = getRecordingTextLog(recording);
  if (!textLog) return;

  toast.custom(
    (toastInstance) => (
      <div
        className={`event-log-toast${toastInstance.visible ? ' event-log-toast--visible' : ''}`}
      >
        <div className="event-log-toast__header">
          <span className="event-log-toast__dot" />
          <span className="event-log-toast__title">New event</span>
          <span className="event-log-toast__camera">{recording.camera_id}</span>
        </div>
        <div className="event-log-toast__body">{textLog}</div>
      </div>
    ),
    {
      duration: 6500,
      id: `recording-log-${recording.id}`,
      position: 'top-right',
    }
  );
};

function App() {
  const [cameras, setCameras] = useState([]);
  const [recordings, setRecordings] = useState([]);
  const [systemInfo, setSystemInfo] = useState({});
  const [loading, setLoading] = useState(true);
  const [authLoading, setAuthLoading] = useState(false);
  const [authError, setAuthError] = useState('');
  const [navOpen, setNavOpen] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(true);
  const [apiEndpoint, setApiEndpoint] = useState(() => getApiEndpointSettings());
  const [customEndpointInput, setCustomEndpointInput] = useState(() => (
    getApiEndpointSettings().customBaseUrl || ''
  ));
  const [customEndpointError, setCustomEndpointError] = useState('');
  const [localDeviceIdInput, setLocalDeviceIdInput] = useState(() => (
    getApiEndpointSettings().localDeviceId || ''
  ));
  const [minimalMode, setMinimalMode] = useState(() => getStoredMinimalMode());
  const [theme, setTheme] = useState(() => getStoredTheme());
  const [installPrompt, setInstallPrompt] = useState(null);
  const [isInstalledApp, setIsInstalledApp] = useState(() => isRunningAsInstalledApp());
  const knownRecordingIdsRef = useRef(new Set());
  const dataLoadedRef = useRef(false);
  const recordingQueryRef = useRef({ ...EMPTY_RECORDING_PAGINATION, requestId: 0 });
  const [recordingPagination, setRecordingPagination] = useState(EMPTY_RECORDING_PAGINATION);
  const [recordingEventsEnabled, setRecordingEventsEnabled] = useState(false);
  const { minimalModeForced, effectiveMinimalMode } = useMemo(() => (
    getMinimalModeState({ storedMinimalMode: minimalMode, apiEndpoint })
  ), [apiEndpoint, minimalMode]);
  const streamingFeatures = useMemo(() => setupStreamingFeatures({
    minimalMode: effectiveMinimalMode,
    requestedStreamMode: systemInfo?.settings?.live_stream_mode ?? 'mjpeg',
    requestedPlaybackMode: systemInfo?.settings?.clip_playback_mode ?? 'file',
  }), [
    effectiveMinimalMode,
    systemInfo?.settings?.clip_playback_mode,
    systemInfo?.settings?.live_stream_mode,
  ]);
  const onvifEventsEnabled = systemInfo?.settings?.onvif_events_enabled === true;

  useEffect(() => {
    const handleBeforeInstallPrompt = (event) => {
      event.preventDefault();
      setInstallPrompt(event);
    };
    const handleAppInstalled = () => {
      setInstallPrompt(null);
      setIsInstalledApp(true);
      toast.success('SecAI installed');
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    window.addEventListener('appinstalled', handleAppInstalled);
    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
      window.removeEventListener('appinstalled', handleAppInstalled);
    };
  }, []);

  // Load initial application data and determine whether the saved session is authenticated.
  useEffect(() => {
    const bootstrap = async () => {
      setLoading(true);
      try {
        await selectPreferredApiEndpoint();
        setApiEndpoint(getApiEndpointSettings());
        await loadCoreData();
        setIsAuthenticated(true);
      } catch (error) {
        const statusCode = error?.response?.status;
        if (statusCode === 401) {
          setIsAuthenticated(false);
          api.clearAccessToken();
        } else {
          setIsAuthenticated(false);
          setAuthError('Backend is unavailable. Select a network endpoint and try again.');
        }
      } finally {
        setLoading(false);
      }
    };

    bootstrap();
  }, []);

  // While the frontend is visible, periodically select the first healthy URL
  // by priority. Reloading cleanly reconnects API, WebRTC and sockets.
  useEffect(() => {
    let checking = false;

    const checkForBetterEndpoint = async () => {
      if (document.visibilityState !== 'visible' || checking) return;
      checking = true;
      try {
        const selected = await selectPreferredApiEndpoint();
        if (selected?.changed) {
          window.location.reload();
        }
      } finally {
        checking = false;
      }
    };

    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        checkForBetterEndpoint();
      }
    };
    const intervalId = window.setInterval(
      checkForBetterEndpoint,
      ENDPOINT_PRIORITY_CHECK_INTERVAL_MS,
    );
    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
      window.clearInterval(intervalId);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  // Maintain the WebRTC data channel and fall back to WebSocket when unavailable.
  useEffect(() => {
    if (!isAuthenticated) {
      return;
    }

    const handleMessage = (message) => {
      switch (message.type) {
        case 'recording.upsert':
          if (
            recordingQueryRef.current.date
            && recordingQueryRef.current.date !== 'latest'
            && getRecordingDateKey(message.payload) !== recordingQueryRef.current.date
          ) {
            break;
          }
          setRecordings(prev => {
            const recording = message.payload;
            const exists = prev.some(item => item.id === recording.id);
            const known = knownRecordingIdsRef.current;
            const shouldNotify = dataLoadedRef.current
              && !known.has(recording.id)
              && String(recording.status || '').toLowerCase() === 'completed';
            known.add(recording.id);
            if (shouldNotify) {
              showRecordingNotification(recording);
            }
            return exists
              ? prev.map(item => item.id === recording.id ? recording : item)
              : [recording, ...prev];
          });
          break;
        case 'recording.deleted':
          setRecordings(prev => prev.filter(
            item => item.id !== message.payload.recording_id
          ));
          break;
        case 'camera.metrics':
          window.dispatchEvent(new CustomEvent('nvr-camera-metrics', {
            detail: message.payload,
          }));
          break;
        case 'camera_added':
          setCameras(prev => [...prev, message.camera]);
          break;
        case 'camera_updated':
          setCameras(prev => prev.map(c => c.id === message.camera.id ? message.camera : c));
          break;
        case 'camera_deleted':
          setCameras(prev => prev.filter(c => c.id !== message.camera_id));
          break;
        case 'recording_started':
          if (
            !recordingQueryRef.current.date
            || recordingQueryRef.current.date === 'latest'
            || getRecordingDateKey(message.recording) === recordingQueryRef.current.date
          ) {
            setRecordings(prev => [...prev, message.recording]);
          }
          setCameras(prev => prev.map(c =>
            c.id === message.camera_id
              ? { ...c, status: 'recording', is_recording: true, recording_id: message.recording.id }
              : c
          ));
          break;
        case 'recording_stopped':
          setCameras(prev => prev.map(c =>
            c.id === message.camera_id
              ? { ...c, status: 'online', is_recording: false, recording_id: null }
              : c
          ));
          break;
        default:
          break;
      }
    };

    return connectApplicationDataChannel({
      onMessage: handleMessage,
      includeRecordingEvents: recordingEventsEnabled,
    });
  }, [isAuthenticated, recordingEventsEnabled]);

  const handleLogin = async (password, stayLoggedIn) => {
    setAuthLoading(true);
    setAuthError('');
    try {
      const response = await api.login(password);
      const token = response?.data?.access_token;
      if (!token) {
        setAuthError('Login failed: no access token returned.');
        return;
      }
      api.setAccessToken(token, stayLoggedIn);
      setIsAuthenticated(true);
      setLoading(true);
      try {
        await loadCoreData();
      } catch (initialDataError) {
        if (initialDataError?.response?.status === 401) {
          api.clearAccessToken();
          setIsAuthenticated(false);
          setAuthError('Login succeeded, but the new session was rejected by the backend.');
          return;
        }
        console.error('Login succeeded, but initial data loading failed:', initialDataError);
        toast.error('Login succeeded, but cameras and system data could not be loaded yet.');
      }
    } catch (error) {
      setIsAuthenticated(false);
      setAuthError(
        error?.response?.data?.detail
        || (error?.response ? 'Login failed.' : 'Backend is unavailable at the selected endpoint.')
      );
    } finally {
      setLoading(false);
      setAuthLoading(false);
    }
  };

  const handleLogout = () => {
    api.clearAccessToken();
    setIsAuthenticated(false);
    setCameras([]);
    setRecordings([]);
    recordingQueryRef.current = { ...EMPTY_RECORDING_PAGINATION, requestId: 0 };
    setRecordingPagination(EMPTY_RECORDING_PAGINATION);
    setSystemInfo({});
  };

  const reloadForEndpointChange = async (baseUrl) => {
    toast.success(`Backend set to ${baseUrl}`);
    setLoading(true);
    try {
      await loadCoreData();
      const requestId = recordingQueryRef.current.requestId + 1;
      recordingQueryRef.current = { ...EMPTY_RECORDING_PAGINATION, requestId };
      setRecordingPagination(EMPTY_RECORDING_PAGINATION);
      setRecordings([]);
      knownRecordingIdsRef.current = new Set();
    } catch (error) {
      const statusCode = error?.response?.status;
      if (statusCode === 401) {
        api.clearAccessToken();
        setIsAuthenticated(false);
      } else {
        toast.error('Failed to refresh data from the selected backend.');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleApiEndpointModeChange = async (event) => {
    const mode = event.target.value;
    setCustomEndpointError('');

    if (mode === API_ENDPOINT_MODES.CUSTOM) {
      const next = {
        ...getApiEndpointSettings(),
        mode,
      };
      setApiEndpoint(next);
      if (!customEndpointInput) {
        setCustomEndpointInput(next.customBaseUrl || '');
      }
      return;
    }

    const selectedEndpoint = apiEndpoint.options.find(option => option.value === mode);
    if (selectedEndpoint && !selectedEndpoint.baseUrl) {
      setCustomEndpointError(`${selectedEndpoint.label} endpoint is not available.`);
      return;
    }

    const baseUrl = setApiEndpointMode(mode);
    setApiEndpoint(getApiEndpointSettings());
    await reloadForEndpointChange(baseUrl);
  };

  const handleCustomEndpointApply = async () => {
    try {
      const baseUrl = setCustomApiBaseUrl(customEndpointInput);
      setCustomEndpointInput(baseUrl);
      setApiEndpoint(getApiEndpointSettings());
      setCustomEndpointError('');
      await reloadForEndpointChange(baseUrl);
    } catch (error) {
      setCustomEndpointError(error.message);
    }
  };

  const handleCustomEndpointBlur = () => {
    if (!customEndpointInput.trim()) {
      return;
    }
    try {
      setCustomEndpointInput(normalizeApiBaseUrl(customEndpointInput));
      setCustomEndpointError('');
    } catch (error) {
      setCustomEndpointError(error.message);
    }
  };

  const handleLoginEndpointModeChange = (event) => {
    const mode = event.target.value;
    setCustomEndpointError('');
    if (mode === API_ENDPOINT_MODES.CUSTOM) {
      setApiEndpoint({ ...getApiEndpointSettings(), mode });
      return;
    }
    const selectedEndpoint = apiEndpoint.options.find(option => option.value === mode);
    if (!selectedEndpoint?.baseUrl && mode !== API_ENDPOINT_MODES.LOCAL) {
      setCustomEndpointError(`${selectedEndpoint?.label || 'Selected'} endpoint is not available.`);
      return;
    }
    setApiEndpointMode(mode);
    setApiEndpoint(getApiEndpointSettings());
    setAuthError('');
  };

  const handleLoginLocalEndpointApply = () => {
    try {
      setLocalDeviceId(localDeviceIdInput);
      setLocalDeviceIdInput(normalizeLocalDeviceId(localDeviceIdInput));
      setApiEndpoint(getApiEndpointSettings());
      setCustomEndpointError('');
      setAuthError('');
    } catch (error) {
      setCustomEndpointError(error.message);
    }
  };

  const handleLoginCustomEndpointApply = () => {
    try {
      const baseUrl = setCustomApiBaseUrl(customEndpointInput);
      setCustomEndpointInput(baseUrl);
      setApiEndpoint(getApiEndpointSettings());
      setCustomEndpointError('');
      setAuthError('');
    } catch (error) {
      setCustomEndpointError(error.message);
    }
  };

  const handleMinimalModeChange = (enabled) => {
    if (minimalModeForced && !enabled) {
      toast.error('Minimal mode is required for non-local API endpoints');
      return;
    }
    setMinimalMode(enabled);
    setStoredMinimalMode(enabled);
    toast.success(enabled ? 'Minimal mode enabled' : 'Full navigation enabled');
  };

  const handleThemeChange = (nextTheme) => {
    const normalizedTheme = nextTheme === THEMES.DARK ? THEMES.DARK : THEMES.DEFAULT;
    setTheme(normalizedTheme);
    localStorage.setItem(THEME_STORAGE_KEY, normalizedTheme);
    toast.success(normalizedTheme === THEMES.DARK ? 'Dark theme enabled' : 'Default theme enabled');
  };

  const handleInstallApp = async () => {
    if (!window.isSecureContext) {
      toast.error('Installation requires HTTPS. Open SecAI from its HTTPS address.');
      return;
    }

    if (!installPrompt) {
      const isIos = /iphone|ipad|ipod/i.test(window.navigator.userAgent);
      if (isIos) {
        toast('In Safari, use Share → Add to Home Screen.');
      } else {
        toast('Install is not available yet. Reload the page and check the browser install menu.');
      }
      return;
    }

    await installPrompt.prompt();
    await installPrompt.userChoice;
    setInstallPrompt(null);
  };

  const handleReloadNetworkEndpoints = async () => {
    const systemRes = await api.getSystemInfo(true);
    setDiscoveredApiEndpoints(systemRes.data?.network_endpoints || {});
    setApiEndpoint(getApiEndpointSettings());
    setSystemInfo(systemRes.data || {});
  };

  const loadCoreData = async () => {
    const [camerasRes, systemRes] = await Promise.all([
      api.getCameras(),
      api.getSystemInfo(),
    ]);
    console.log('Core data loaded:', camerasRes.data, systemRes.data);
    setDiscoveredApiEndpoints(systemRes.data?.network_endpoints || {});
    setApiEndpoint(getApiEndpointSettings());
    setCameras(camerasRes.data);
    setSystemInfo(systemRes.data);
  };

  const fetchRecordingPage = useCallback(async ({
    cameraId = null,
    recordingDate = null,
    reset = false,
  } = {}) => {
    const normalizedCameraId = cameraId || null;
    const normalizedDate = recordingDate || null;
    const current = recordingQueryRef.current;
    const queryChanged = (
      current.cameraId !== normalizedCameraId
      || current.date !== normalizedDate
    );
    if (current.loading && !queryChanged && !reset) {
      return;
    }
    const shouldReset = reset || queryChanged || !current.initialized;

    if (!shouldReset && (current.loading || !current.hasMore)) {
      return;
    }

    const offset = shouldReset ? 0 : current.loaded;
    const requestId = current.requestId + 1;
    recordingQueryRef.current = {
      ...current,
      cameraId: normalizedCameraId,
      date: normalizedDate,
      loading: true,
      error: '',
      requestId,
      ...(shouldReset ? { loaded: 0, total: 0, hasMore: false, initialized: false } : {}),
    };
    setRecordingPagination((previous) => ({
      ...previous,
      cameraId: normalizedCameraId,
      date: normalizedDate === 'latest' ? previous.date : normalizedDate,
      loading: true,
      error: '',
      ...(shouldReset ? { loaded: 0, total: 0, hasMore: false, initialized: false } : {}),
    }));
    if (shouldReset) {
      setRecordings([]);
    }

    try {
      const response = await api.getRecordingsSummary(
        normalizedCameraId,
        normalizedDate ? EVENT_RECORDINGS_PAGE_SIZE : RECORDINGS_PAGE_SIZE,
        offset,
        normalizedDate,
      );
      if (recordingQueryRef.current.requestId !== requestId) return;

      const payload = response.data || {};
      const pageItems = Array.isArray(payload.items) ? payload.items : [];
      const loaded = offset + pageItems.length;
      const total = Number(payload.total) || loaded;
      const resolvedDate = payload.date || (normalizedDate === 'latest' ? null : normalizedDate);
      const nextState = {
        cameraId: normalizedCameraId,
        date: resolvedDate,
        loaded,
        total,
        hasMore: Boolean(payload.has_more),
        loading: false,
        initialized: true,
        error: '',
        requestId,
      };
      recordingQueryRef.current = nextState;
      setRecordingPagination(nextState);
      setRecordings((previous) => {
        if (shouldReset) return pageItems;
        const existingIds = new Set(previous.map((recording) => recording.id));
        return [
          ...previous,
          ...pageItems.filter((recording) => !existingIds.has(recording.id)),
        ];
      });
      if (shouldReset) {
        knownRecordingIdsRef.current = new Set(pageItems.map((recording) => recording.id));
      } else {
        pageItems.forEach((recording) => knownRecordingIdsRef.current.add(recording.id));
      }
      dataLoadedRef.current = true;
    } catch (error) {
      if (recordingQueryRef.current.requestId !== requestId) return;
      const message = error?.response?.data?.detail || error?.message || 'Failed to load recordings';
      recordingQueryRef.current = {
        ...recordingQueryRef.current,
        loading: false,
        initialized: true,
        error: String(message),
      };
      setRecordingPagination((previous) => ({
        ...previous,
        loading: false,
        initialized: true,
        error: String(message),
      }));
      throw error;
    }
  }, []);

  const ensureRecordingData = useCallback((cameraId = null, recordingDate = null) => {
    setRecordingEventsEnabled(true);
    return fetchRecordingPage({ cameraId, recordingDate });
  }, [fetchRecordingPage]);

  const releaseRecordingData = useCallback(() => {
    setRecordingEventsEnabled(false);
  }, []);

  const loadMoreRecordings = useCallback(() => (
    fetchRecordingPage({
      cameraId: recordingQueryRef.current.cameraId,
      recordingDate: recordingQueryRef.current.date,
    })
  ), [fetchRecordingPage]);

  const refreshRecordingData = useCallback(() => {
    if (!recordingQueryRef.current.initialized && !recordingQueryRef.current.loading) {
      return Promise.resolve();
    }
    return fetchRecordingPage({
      cameraId: recordingQueryRef.current.cameraId,
      recordingDate: recordingQueryRef.current.date,
      reset: true,
    });
  }, [fetchRecordingPage]);

  // Refresh app data when an archive load/unload changes recordings or cameras.
  useEffect(() => {
    const refresh = () => {
      Promise.all([loadCoreData(), refreshRecordingData()]).catch((error) => {
        console.error('Failed to refresh data after archive change:', error);
      });
    };
    window.addEventListener('archive-loaded', refresh);
    window.addEventListener('archive-unloaded', refresh);
    return () => {
      window.removeEventListener('archive-loaded', refresh);
      window.removeEventListener('archive-unloaded', refresh);
    };
  }, [refreshRecordingData]);

  if (loading) {
    return (
      <div className="app-loading">
        <div className="loading"></div>
        <p>Loading NVR Server...</p>
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
      <LoginScreen
        onLogin={handleLogin}
        loading={authLoading}
        error={authError}
        apiEndpoint={apiEndpoint}
        localDeviceIdInput={localDeviceIdInput}
        onLocalDeviceIdInputChange={setLocalDeviceIdInput}
        customEndpointInput={customEndpointInput}
        endpointError={customEndpointError}
        onEndpointModeChange={handleLoginEndpointModeChange}
        onLocalEndpointApply={handleLoginLocalEndpointApply}
        onCustomEndpointInputChange={setCustomEndpointInput}
        onCustomEndpointBlur={handleCustomEndpointBlur}
        onCustomEndpointApply={handleLoginCustomEndpointApply}
      />
    );
  }

  return (
    <RouterComponent>
      <div className={`app theme-${theme}`}>
        {navOpen && (
          <div className="nav-overlay" onClick={() => setNavOpen(false)} aria-hidden="true" />
        )}
        <Toaster 
          position="top-right"
          toastOptions={{
            duration: 4000,
            style: {
              background: '#2a2a2a',
              color: '#ffffff',
              border: '1px solid #4a4a4a'
            }
          }}
        />
        
        <button
          type="button"
          className="hamburger-btn"
          aria-label={navOpen ? 'Close menu' : 'Open menu'}
          aria-expanded={navOpen}
          onClick={() => setNavOpen(o => !o)}
        >
          <span /><span /><span />
        </button>

        <nav className={`sidebar${navOpen ? ' sidebar--open' : ''}`}>
          <div className="sidebar-header">
            <h2 className="sidebar-title">SecAI</h2>
          </div>
          
          <div className="sidebar-nav">
            <NavLink to="/" className="nav-link" end onClick={() => setNavOpen(false)}>
              <Monitor size={20} />
              Event
            </NavLink>
            <NavLink to="/gallery" className="nav-link" onClick={() => setNavOpen(false)}>
              <Users size={20} />
              Search
            </NavLink>
            <NavLink to="/cameras" className="nav-link" onClick={() => setNavOpen(false)}>
              <Camera size={20} />
              Camera
            </NavLink>
            {!effectiveMinimalMode && (
              <NavLink to="/zones" className="nav-link" onClick={() => setNavOpen(false)}>
                <MapPin size={20} />
                Zones
              </NavLink>
            )}
            {!effectiveMinimalMode && (
              <>
                <NavLink to="/recordings" className="nav-link" onClick={() => setNavOpen(false)}>
                  <Camera size={20} />
                  Recordings
                </NavLink>
                <NavLink to="/dashboard" className="nav-link" onClick={() => setNavOpen(false)}>
                  <BarChart3 size={20} />
                  Dashboard
                </NavLink>
                <NavLink to="/settings" className="nav-link" onClick={() => setNavOpen(false)}>
                  <Settings size={20} />
                  Settings
                </NavLink>
              </>
            )}
            <NavLink to="/admin" className="nav-link" onClick={() => setNavOpen(false)}>
              <Server size={20} />
              Admin
            </NavLink>
            <NavLink to="/network" className="nav-link" onClick={() => setNavOpen(false)}>
              <NetworkIcon size={20} />
              Network
            </NavLink>
            {!isInstalledApp && (
              <button
                type="button"
                className={`nav-link install-app-button${installPrompt ? ' install-app-button--ready' : ''}`}
                onClick={handleInstallApp}
                title={installPrompt ? 'Install SecAI' : 'Installation requires browser approval and HTTPS'}
              >
                <Download size={20} />
                Install
              </button>
            )}
          </div>
        </nav>

        <main className="main-content">
          <Routes>
            <Route 
              path="/" 
              element={
                <EventView
                  cameras={cameras}
                  recordings={recordings}
                  ensureRecordings={ensureRecordingData}
                  releaseRecordings={releaseRecordingData}
                  recordingPagination={recordingPagination}
                  onLoadMoreRecordings={loadMoreRecordings}
                  onvifEventsEnabled={onvifEventsEnabled}
                  activePlaybackModes={streamingFeatures.activePlaybackModes}
                  initialPlaybackMode={streamingFeatures.playbackMode}
                />
              } 
            />
            <Route 
              path="/dashboard" 
              element={
                <Dashboard 
                  cameras={cameras}
                  recordings={recordings}
                  systemInfo={systemInfo}
                  ensureRecordings={ensureRecordingData}
                  releaseRecordings={releaseRecordingData}
                  recordingPagination={recordingPagination}
                  onLoadMoreRecordings={loadMoreRecordings}
                />
              } 
            />
            <Route 
              path="/cameras" 
              element={
                <CameraList 
                  cameras={cameras}
                  setCameras={setCameras}
                  streamMode={streamingFeatures.streamMode}
                  activeStreamModes={streamingFeatures.activeStreamModes}
                  minimalMode={effectiveMinimalMode}
                />
              } 
            />
            <Route 
              path="/live" 
              element={
                <EventView
                  cameras={cameras}
                  recordings={recordings}
                  ensureRecordings={ensureRecordingData}
                  releaseRecordings={releaseRecordingData}
                  recordingPagination={recordingPagination}
                  onLoadMoreRecordings={loadMoreRecordings}
                  onvifEventsEnabled={onvifEventsEnabled}
                  activePlaybackModes={streamingFeatures.activePlaybackModes}
                  initialPlaybackMode={streamingFeatures.playbackMode}
                />
              } 
            />
            <Route
              path="/zones"
              element={<ZoneStudio cameras={cameras} />}
            />
            <Route
              path="/gallery"
              element={<PersonGallery cameras={cameras} />}
            />
            <Route 
              path="/recordings" 
              element={
                <RecordingList 
                  recordings={recordings}
                  setRecordings={setRecordings}
                  cameras={cameras}
                  ensureRecordings={ensureRecordingData}
                  releaseRecordings={releaseRecordingData}
                  recordingPagination={recordingPagination}
                  onLoadMoreRecordings={loadMoreRecordings}
                  activePlaybackModes={streamingFeatures.activePlaybackModes}
                  initialPlaybackMode={streamingFeatures.playbackMode}
                />
              } 
            />
            <Route 
              path="/settings" 
              element={(
                <SystemSettings
                  systemInfo={systemInfo}
                  cameras={cameras}
                  setCameras={setCameras}
                  onSettingsUpdated={(updatedSettings) => setSystemInfo((previous) => ({
                    ...previous,
                    settings: {
                      ...(previous.settings || {}),
                      ...updatedSettings,
                    },
                  }))}
                />
              )}
            />
            <Route
              path="/admin"
              element={
                <Admin
                  apiEndpoint={apiEndpoint}
                  customEndpointInput={customEndpointInput}
                  customEndpointError={customEndpointError}
                  onApiEndpointModeChange={handleApiEndpointModeChange}
                  onCustomEndpointInputChange={(event) => {
                    setCustomEndpointInput(event.target.value);
                    setCustomEndpointError('');
                  }}
                  onCustomEndpointBlur={handleCustomEndpointBlur}
                  onCustomEndpointApply={handleCustomEndpointApply}
                  onLogout={handleLogout}
                  minimalMode={effectiveMinimalMode}
                  minimalModeForced={minimalModeForced}
                  onMinimalModeChange={handleMinimalModeChange}
                  theme={theme}
                  onThemeChange={handleThemeChange}
                  onReloadNetworkEndpoints={handleReloadNetworkEndpoints}
                />
              }
            />
            <Route
              path="/network"
              element={<Network />}
            />
          </Routes>
        </main>
      </div>
    </RouterComponent>
  );
}

export default App;
