import React, { useCallback, useEffect, useMemo, useState, useRef } from 'react';
import { createPortal } from 'react-dom';
import { Camera, ChevronLeft, ChevronRight, Loader, X } from 'lucide-react';
import { api } from '../../api';
import {
  TimeFrameBadge,
  FrameStepButtons,
  getRecordingMetadata,
  formatPlaybackTime,
  resolvePlaybackFps,
  getRecordingPlaybackViewData,
  buildRecordingsByCamera,
  buildCameraRows,
  DEFAULT_TIMEZONE_OFFSET,
  getCurrentDayInTimezone,
  getRecordingLocalDate,
  normalizeTimezone,
  recordingMatchesMetricFilters,
  recordingHasDefaultEventSignal,
  shiftLocalDate,
  downloadRecordingFile,
} from './EventViewUtils';
import { SimpleMotionPlot, ChartCard, OverlayButton, ReelCard, EventLogBlock, OnvifEventBlock, RecordedWebRTCPlayer, showRecordingPlaybackLimitToast } from './EventViewCards';
import { createPersistentClipChannel } from '../../transports/clip_channel';
import './EventView.css';

const MOTION_COLORS = {
  activity: '#009688',
  bgDiff: '#5c6bc0',
  loudness: '#ff9800',
  duration: '#e91e63',
  person: '#8e24aa',
  loitering: '#2e7d32',
  burglary: '#ef6c00',
  fight: '#c62828',
};

const DEFAULT_CHART_THRESHOLDS = {
  person: 0,
  duration: 0,
  activity: 0,
  change: 0,
  loitering: 0,
  burglary: 0,
  fight: 0,
  audio: 0,
};

const DEFAULT_PLAYBACK_MODES = ['file', 'webrtc-p2p'];

const normalizePlaybackMode = (mode, allowedModes = DEFAULT_PLAYBACK_MODES) => (
  allowedModes.includes(mode) ? mode : allowedModes[0]
);

const REELS_PER_PAGE = 25;
const LIVE_METRICS_UPDATE_INTERVAL_MS = 1000;

/**
 * Main EventView component for displaying camera recordings with interactive timeline
 * Provides video playback, timeline navigation, and recording management
 */
const EventView = ({
  recordings = [],
  cameras = [],
  ensureRecordings,
  releaseRecordings,
  recordingPagination = {},
  onLoadMoreRecordings,
  onvifEventsEnabled = false,
  activePlaybackModes = DEFAULT_PLAYBACK_MODES,
  initialPlaybackMode,
}) => {
  const initialRecordingDateRef = useRef(
    window.history.state?.usr?.date || 'latest',
  );

  useEffect(() => {
    ensureRecordings?.(null, initialRecordingDateRef.current).catch((error) => {
      console.error('Failed to load event recordings:', error);
    });
    return () => releaseRecordings?.();
  }, [ensureRecordings, releaseRecordings]);

  const validRecordings = useMemo(
    () => (Array.isArray(recordings) ? recordings : []),
    [recordings],
  );
  const validCameras = useMemo(
    () => (Array.isArray(cameras) ? cameras : []),
    [cameras],
  );

  // Local UI state does not mutate the recording objects received from App.
  const [removedRecordingIds, setRemovedRecordingIds] = useState({});
  const [markedIds, setMarkedIds] = useState({});
  const [showMarkedOnly, setShowMarkedOnly] = useState(false);
  const [showAllEvents, setShowAllEvents] = useState(false);
  const [pageByCam, setPageByCam] = useState({});
  const [serverTimezone, setServerTimezone] = useState(() => normalizeTimezone(null));
  const timezoneOffset = serverTimezone?.offset || DEFAULT_TIMEZONE_OFFSET;
  const timezoneLabel = `${serverTimezone?.name || 'UTC'} (${timezoneOffset})`;

  // Base set is reused by empty states, marking, and camera grouping.
  const availableCompletedRecordings = useMemo(
    () => validRecordings.filter((recording) => (
      (recording?.status || '').toLowerCase() === 'completed'
      && !removedRecordingIds[recording.id]
    )),
    [removedRecordingIds, validRecordings],
  );

  const completedRecordings = useMemo(
    () => availableCompletedRecordings.filter((recording) => {
      if (showMarkedOnly && !markedIds[recording.id]) return false;
      return true;
    }),
    [availableCompletedRecordings, markedIds, showMarkedOnly],
  );

  // Playback and selection state shared by cards and the expanded player.
  const [playingId, setPlayingId] = useState(null);
  const [highlightedRecordingId, setHighlightedRecordingId] = useState(null);
  const [focusedRecordingId, setFocusedRecordingId] = useState(null);
  const allowedPlaybackModes = useMemo(
    () => (activePlaybackModes.length > 0 ? activePlaybackModes : DEFAULT_PLAYBACK_MODES),
    [activePlaybackModes],
  );
  const [playbackMode, setPlaybackMode] = useState(() => (
    normalizePlaybackMode(initialPlaybackMode || api.getRecordingPlaybackMode(), allowedPlaybackModes)
  ));
  const [clipController, setClipController] = useState(null);
  const [playbackStatsById, setPlaybackStatsById] = useState({});
  const [expandedContext, setExpandedContext] = useState(null);
  const [expandedView, setExpandedView] = useState('video');
  const [expandedPersonIndex, setExpandedPersonIndex] = useState(0);
  const [personsByRecording, setPersonsByRecording] = useState({});
  const [overlayIds, setOverlayIds] = useState({});
  const [serverCurrentDay, setServerCurrentDay] = useState(() => getCurrentDayInTimezone(DEFAULT_TIMEZONE_OFFSET));
  const [liveMetricsByCamera, setLiveMetricsByCamera] = useState({});
  const [onvifEventsByCamera, setOnvifEventsByCamera] = useState({});
  const [onvifListenerByCamera, setOnvifListenerByCamera] = useState({});
  const [onvifLoadingByCamera, setOnvifLoadingByCamera] = useState({});
  const [onvifErrorByCamera, setOnvifErrorByCamera] = useState({});

  // Chart controls filter the recording summaries already held in memory.
  const [chartToggles, setChartToggles] = useState({
    person: false,
    duration: false,
    activity: false,
    change: false,
    loitering: true,
    burglary: true,
    fight: false,
    audio: true,
  });
  const [chartDate, setChartDate] = useState(() => {
    const navDate = window.history.state?.usr?.date;
    return navDate || getCurrentDayInTimezone(DEFAULT_TIMEZONE_OFFSET);
  });

  // Return today's date using server time when available.
  const getTodayLocal = useCallback(() => {
    return serverCurrentDay || getCurrentDayInTimezone(timezoneOffset);
  }, [serverCurrentDay, timezoneOffset]);

  // Move the chart date by a whole local calendar day.
  const shiftDate = useCallback((delta) => {
    const nextDate = shiftLocalDate(chartDate, delta);
    setChartDate(nextDate);
    setPageByCam({});
    ensureRecordings?.(null, nextDate).catch((error) => {
      console.error(`Failed to load events for ${nextDate}:`, error);
    });
  }, [chartDate, ensureRecordings]);

  // DOM and gesture state stays in refs to avoid rerendering during dragging.
  const videoRefs = useRef({});
  const expandedVideoRefs = useRef({});
  const reelCardRefs = useRef({});
  const rowScrollRefs = useRef({});
  const seekStateRef = useRef({});
  const personSwipeStartRef = useRef(null);
  const focusResetTimerRef = useRef(null);
  const navigationFocusHandledRef = useRef(false);
  const navigationLoadOffsetRef = useRef(null);
  const pendingLiveMetricsRef = useRef({});
  const liveMetricsFlushTimerRef = useRef(null);
  const lastLiveMetricsFlushRef = useRef(0);

  // Check a recording against the currently enabled metric filters.
  const recordingMatchesChartFilters = useCallback(
    (recording) => recordingMatchesMetricFilters(recording, chartToggles, DEFAULT_CHART_THRESHOLDS),
    [chartToggles],
  );

  const recordingMatchesDateAndEventFilters = useCallback((recording) => {
    if (getRecordingLocalDate(recording, timezoneOffset) !== chartDate) return false;
    if (!showAllEvents && !recordingHasDefaultEventSignal(recording)) return false;
    return true;
  }, [chartDate, showAllEvents, timezoneOffset]);

  // Expanded playback owns the media while open, so inline players are unloaded.
  const stopInlineMediaPlayback = useCallback((exceptRecordingId = null) => {
    Object.entries(videoRefs.current).forEach(([recordingId, element]) => {
      if (exceptRecordingId !== null && String(recordingId) === String(exceptRecordingId)) {
        return;
      }

      if (!element) {
        return;
      }

      const tag = String(element.tagName || '').toUpperCase();

      if (tag === 'VIDEO') {
        try {
          element.pause();
          element.srcObject = null;
          element.removeAttribute('src');
          element.load();
        } catch (_error) {
        }
      }

      if (tag === 'IMG') {
        try {
          element.src = '';
        } catch (_error) {
        }
      }
    });
  }, []);

  useEffect(() => {
    const webRtcModes = allowedPlaybackModes.filter((mode) => mode.startsWith('webrtc-'));
    if (webRtcModes.length === 0) {
      setClipController(null);
      return undefined;
    }

    const controller = createPersistentClipChannel({
      turnOnly: webRtcModes.every((mode) => mode === 'webrtc-turn'),
      onState: ({ state, error, timing }) => {
        if (state === 'failed') {
          console.warn('Persistent clip WebRTC connection failed:', error);
        }
        if (state === 'playing') {
          console.debug('Persistent clip WebRTC switch timing:', timing);
        }
      },
    });
    controller.ready.catch(() => {});
    setClipController(controller);
    return () => {
      controller.close();
      setClipController((current) => (current === controller ? null : current));
    };
  }, [allowedPlaybackModes]);

  useEffect(() => {
    const nextMode = normalizePlaybackMode(initialPlaybackMode || playbackMode, allowedPlaybackModes);
    if (nextMode !== playbackMode) {
      stopInlineMediaPlayback();
      setPlayingId(null);
      setPlaybackMode(nextMode);
      api.setRecordingPlaybackMode(nextMode);
    }
  }, [allowedPlaybackModes, initialPlaybackMode, playbackMode, stopInlineMediaPlayback]);

  // Toggle the marked state of a recording card.
  const handleToggleMark = useCallback((recordingId) => {
    setMarkedIds((m) => ({ ...m, [recordingId]: !m[recordingId] }));
  }, []);

  const markedCount = useMemo(
    () => Object.values(markedIds).filter(Boolean).length,
    [markedIds],
  );

  // Build the camera rows once all local filters have been applied.
  const recordingsByCamera = useMemo(
    () => buildRecordingsByCamera(completedRecordings),
    [completedRecordings],
  );
  const metricFilteredRecordingsByCamera = useMemo(
    () => Object.entries(recordingsByCamera).reduce((acc, [cameraId, recs]) => {
      const filtered = recs.filter(recordingMatchesChartFilters);
      if (filtered.length > 0) {
        acc[cameraId] = filtered;
      }
      return acc;
    }, {}),
    [recordingMatchesChartFilters, recordingsByCamera],
  );
  const allCameraRows = useMemo(
    () => buildCameraRows(metricFilteredRecordingsByCamera, validCameras),
    [metricFilteredRecordingsByCamera, validCameras],
  );
  const filteredCameraRows = useMemo(
    () => allCameraRows.map((row) => ({
      ...row,
      recordings: row.recordings.filter(recordingMatchesDateAndEventFilters),
    })),
    [allCameraRows, recordingMatchesDateAndEventFilters],
  );
  const filteredCameraRowsById = useMemo(
    () => Object.fromEntries(filteredCameraRows.map((row) => [row.cameraId, row])),
    [filteredCameraRows],
  );

  const [selectedCameraId, setSelectedCameraId] = useState(null);

  const cameraRows = useMemo(
    () => (selectedCameraId
      ? filteredCameraRows.filter((row) => row.cameraId === selectedCameraId)
      : filteredCameraRows),
    [filteredCameraRows, selectedCameraId],
  );
  const loadOnvifEvents = useCallback(async (cameraId, silent = false) => {
    if (!onvifEventsEnabled || !cameraId) {
      return;
    }

    if (!silent) {
      setOnvifLoadingByCamera((current) => ({ ...current, [cameraId]: true }));
    }

    try {
      const response = await api.getOnvifEvents(cameraId, 25, true);
      const payload = response?.data || {};
      const normalizedEvents = (Array.isArray(payload.events) ? payload.events : []).map((event) => ({
        timestamp: event?.timestamp || event?.received_at || event?.event_time || null,
        IsMotion: event?.IsMotion ?? event?.is_motion ?? event?.motion ?? null,
        IsPerson: event?.IsPerson ?? event?.is_person ?? event?.person ?? null,
      }));
      setOnvifEventsByCamera((current) => ({
        ...current,
        [cameraId]: normalizedEvents,
      }));
      setOnvifListenerByCamera((current) => ({
        ...current,
        [cameraId]: payload.listener || null,
      }));
      setOnvifErrorByCamera((current) => ({ ...current, [cameraId]: '' }));
    } catch (error) {
      const detail = error?.response?.data?.detail || error?.message || 'Failed to load ONVIF events';
      setOnvifErrorByCamera((current) => ({ ...current, [cameraId]: String(detail) }));
    } finally {
      setOnvifLoadingByCamera((current) => ({ ...current, [cameraId]: false }));
    }
  }, [onvifEventsEnabled]);

  // Merge a playback position update into the selected recording's stats.
  const updatePlaybackStats = (recordingId, patch) => {
    setPlaybackStatsById((current) => ({
      ...current,
      [recordingId]: {
        ...(current[recordingId] || { currentTime: 0, duration: 0 }),
        ...patch,
      },
    }));
  };

  // Track playback progress while ignoring updates generated during seeking.
  const handleVideoTimeUpdate = (recordingId, event) => {
    const seekState = seekStateRef.current[recordingId];
    if (seekState?.isSeeking) {
      return;
    }
    const currentTime = Number(event?.target?.currentTime) || 0;
    const duration = Number(event?.target?.duration) || 0;
    updatePlaybackStats(recordingId, { currentTime, duration });
  };

  // Initialize playback duration and position after media metadata loads.
  const handleVideoLoadedMetadata = (recordingId, event) => {
    const currentTime = Number(event?.target?.currentTime) || 0;
    const duration = Number(event?.target?.duration) || 0;
    updatePlaybackStats(recordingId, { currentTime, duration });
  };

  const handleVideoEnded = (recordingId) => {
    setPlayingId((current) => (current === recordingId ? null : current));
  };

  // Seek the active inline or expanded video to a requested time.
  const handleSeekChange = (recordingId, value, useExpandedRef = false) => {
    const refMap = useExpandedRef ? expandedVideoRefs.current : videoRefs.current;
    const video = refMap[recordingId];
    if (!video) {
      return;
    }
    const nextTime = Number(value);
    if (!Number.isFinite(nextTime)) {
      return;
    }
    video.currentTime = nextTime;
    updatePlaybackStats(recordingId, {
      currentTime: nextTime,
      duration: Number(video.duration) || 0,
    });
  };

  // Pause playback and remember its state when a seek interaction starts.
  const handleSeekStart = (recordingId, useExpandedRef = false) => {
    const refMap = useExpandedRef ? expandedVideoRefs.current : videoRefs.current;
    const video = refMap[recordingId];

    const wasPlaying = !!(video && !video.paused);
    if (wasPlaying) {
      video.pause();
    }

    seekStateRef.current[recordingId] = {
      isSeeking: true,
      wasPlaying,
      useExpandedRef,
    };
  };

  // Resume playback when a seek interaction ends if it was playing before.
  const handleSeekEnd = (recordingId) => {
    const seekState = seekStateRef.current[recordingId];
    if (!seekState) {
      return;
    }

    seekStateRef.current[recordingId] = {
      ...seekState,
      isSeeking: false,
    };

    const refMap = seekState.useExpandedRef ? expandedVideoRefs.current : videoRefs.current;
    const video = refMap[recordingId];
    if (seekState.wasPlaying && video && typeof video.play === 'function') {
      video.play().catch(() => {});
      setPlayingId(recordingId);
    }
  };

  // Advance file playback by exactly one resolved video frame.
  const stepFrame = (recording, direction, useExpandedRef = false) => {
    if (playbackMode !== 'file') {
      return;
    }

    const recordingId = recording.id;

    const refMap = useExpandedRef ? expandedVideoRefs.current : videoRefs.current;
    const video = refMap[recordingId];
    if (!video) {
      return;
    }

    if (!video.paused) {
      video.pause();
      setPlayingId(null);
    }

    const metadata = getRecordingMetadata(recording);
    const fps = resolvePlaybackFps(recording, metadata);

    const frameSeconds = 1 / fps;
    const duration = Number(video.duration) || Number(playbackStatsById[recordingId]?.duration) || 0;
    const maxTime = Math.max(0, duration - frameSeconds);
    const nextTime = Math.min(maxTime, Math.max(0, (Number(video.currentTime) || 0) + (direction * frameSeconds)));

    video.currentTime = nextTime;
    updatePlaybackStats(recordingId, {
      currentTime: nextTime,
      duration,
    });
  };

  // Toggle the clicked recording and stop every other inline player first.
  const handleClick = (recordingId) => {
    if (playingId === recordingId) {
      const video = videoRefs.current[recordingId];
      if (video && typeof video.pause === 'function') {
        video.pause();
      }
      setPlayingId(null);
      return;
    }

    stopInlineMediaPlayback(recordingId);
    setPlayingId(recordingId);
  };

  const changeReelPage = (cameraId, nextPage, totalPages) => {
    const clampedPage = Math.max(0, Math.min(totalPages - 1, nextPage));
    stopInlineMediaPlayback();
    setPlayingId(null);
    setPageByCam((current) => ({ ...current, [cameraId]: clampedPage }));
  };

  // Reveal and focus the reel card selected from the event timeline.
  const handleTimelinePointClick = useCallback((cameraId, recordingId) => {
    setHighlightedRecordingId(recordingId);

    setFocusedRecordingId(recordingId);
    if (focusResetTimerRef.current) {
      clearTimeout(focusResetTimerRef.current);
    }
    focusResetTimerRef.current = setTimeout(() => {
      setFocusedRecordingId((current) => (current === recordingId ? null : current));
    }, 2600);

    const filteredRowRecordings = filteredCameraRowsById[cameraId]?.recordings || [];
    const targetIndex = filteredRowRecordings.findIndex(
      (recording) => String(recording.id) === String(recordingId)
    );
    if (targetIndex >= 0) {
      setSelectedCameraId(cameraId);
      setPageByCam((current) => ({
        ...current,
        [cameraId]: Math.floor(targetIndex / REELS_PER_PAGE),
      }));
    }

    const focusCardInRow = () => {
      const rowElement = rowScrollRefs.current[cameraId];
      const cardElement = reelCardRefs.current[recordingId];
      if (rowElement && cardElement) {
        cardElement.scrollIntoView({
          behavior: 'smooth',
          block: 'nearest',
          inline: 'center',
        });
      }
    };

    requestAnimationFrame(() => {
      requestAnimationFrame(focusCardInRow);
    });
    setTimeout(focusCardInRow, 180);
    setTimeout(focusCardInRow, 420);
  }, [filteredCameraRowsById]);

  // Delete a recording and remove it from local Event View state.
  const handleDeleteRecording = async (recordingId) => {
    const confirmed = window.confirm('Delete this recording?');
    if (!confirmed) {
      return;
    }

    try {
      await api.deleteRecording(recordingId);
      setRemovedRecordingIds((current) => ({ ...current, [recordingId]: true }));
      if (highlightedRecordingId === recordingId) {
        setHighlightedRecordingId(null);
      }
      if (playingId === recordingId) {
        setPlayingId(null);
      }
    } catch (error) {
      console.error('Failed to delete recording:', error);
      window.alert(error?.response?.data?.detail || 'Failed to delete recording');
    }
  };

  // Open a recording in the expanded player and stop inline media.
  const handleOpenExpanded = (cameraId, index, view = 'video') => {
    const recording = filteredCameraRowsById[cameraId]?.recordings?.[index];
    if (!recording) return;

    stopInlineMediaPlayback();
    setExpandedContext({ cameraId, index });
    setExpandedView(view);
    setExpandedPersonIndex(0);
    setPlayingId(null);
  };

  // Close the expanded recording player.
  const handleCloseExpanded = () => {
    setExpandedContext(null);
  };

  // Navigate the expanded player within the currently filtered camera row.
  const handleExpandedNavigate = (direction) => {
    if (!expandedContext) return;

    const rowRecordings = filteredCameraRowsById[expandedContext.cameraId]?.recordings || [];
    if (rowRecordings.length === 0) return;

    const nextIndex = Math.min(
      rowRecordings.length - 1,
      Math.max(0, expandedContext.index + direction)
    );
    const nextRecording = rowRecordings[nextIndex];
    if (!nextRecording || nextIndex === expandedContext.index) {
      return;
    }

    stopInlineMediaPlayback();
    setPlayingId(null);
    setExpandedPersonIndex(0);
    setExpandedContext({ ...expandedContext, index: nextIndex });
  };

  // Lifecycle effects are grouped here so setup and cleanup are easy to audit.

  // Receive live camera metrics dispatched by the application transport.
  useEffect(() => {
    const flushMetrics = () => {
      liveMetricsFlushTimerRef.current = null;
      const pendingMetrics = pendingLiveMetricsRef.current;
      pendingLiveMetricsRef.current = {};
      if (Object.keys(pendingMetrics).length === 0) return;

      lastLiveMetricsFlushRef.current = Date.now();
      setLiveMetricsByCamera((current) => ({
        ...current,
        ...pendingMetrics,
      }));
    };

    const handleMetrics = (event) => {
      const metrics = event.detail;
      if (!metrics?.camera_id) return;
      pendingLiveMetricsRef.current[metrics.camera_id] = metrics;

      if (liveMetricsFlushTimerRef.current !== null) return;
      const elapsed = Date.now() - lastLiveMetricsFlushRef.current;
      const delay = Math.max(0, LIVE_METRICS_UPDATE_INTERVAL_MS - elapsed);
      liveMetricsFlushTimerRef.current = setTimeout(flushMetrics, delay);
    };
    window.addEventListener('nvr-camera-metrics', handleMetrics);
    return () => {
      window.removeEventListener('nvr-camera-metrics', handleMetrics);
      if (liveMetricsFlushTimerRef.current !== null) {
        clearTimeout(liveMetricsFlushTimerRef.current);
        liveMetricsFlushTimerRef.current = null;
      }
      pendingLiveMetricsRef.current = {};
    };
  }, []);

  // Resolve external notification/dashboard navigation, loading older backend
  // pages until the requested recording is available locally.
  useEffect(() => {
    if (navigationFocusHandledRef.current) return undefined;
    const navState = window.history.state?.usr;
    if (!navState?.recordingId || !navState?.cameraId) return undefined;

    const targetRecording = availableCompletedRecordings.find(
      (recording) => String(recording.id) === String(navState.recordingId)
    );
    if (targetRecording) {
      const targetDate = getRecordingLocalDate(targetRecording, timezoneOffset);
      if (targetDate && targetDate !== chartDate) {
        setChartDate(targetDate);
        setPageByCam({});
        return undefined;
      }
      if (!showAllEvents && !recordingHasDefaultEventSignal(targetRecording)) {
        setShowAllEvents(true);
        return undefined;
      }
    }

    const rowRecordings = filteredCameraRowsById[navState.cameraId]?.recordings || [];
    const targetIndex = rowRecordings.findIndex(
      (recording) => String(recording.id) === String(navState.recordingId)
    );
    if (targetIndex >= 0) {
      navigationFocusHandledRef.current = true;
      handleTimelinePointClick(navState.cameraId, navState.recordingId);
      return undefined;
    }

    if (
      recordingPagination.hasMore
      && !recordingPagination.loading
      && navigationLoadOffsetRef.current !== recordingPagination.loaded
    ) {
      navigationLoadOffsetRef.current = recordingPagination.loaded;
      onLoadMoreRecordings?.().catch((error) => {
        console.error('Failed to load the page containing the selected event:', error);
      });
    }
    return undefined;
  }, [
    availableCompletedRecordings,
    chartDate,
    filteredCameraRowsById,
    handleTimelinePointClick,
    onLoadMoreRecordings,
    recordingPagination.hasMore,
    recordingPagination.loaded,
    recordingPagination.loading,
    showAllEvents,
    timezoneOffset,
  ]);

  // Load server timezone information while retaining browser time as fallback.
  useEffect(() => {
    let cancelled = false;
    const loadServerTimezone = async () => {
      try {
        const timezone = await api.getServerTimezone();
        if (cancelled) return;
        const normalizedTimezone = normalizeTimezone(timezone);
        setServerTimezone(normalizedTimezone);
        setServerCurrentDay(getCurrentDayInTimezone(normalizedTimezone.offset));
      } catch (error) {
        console.warn('Failed to load server timezone:', error);
        if (!cancelled) {
          const fallbackTimezone = normalizeTimezone(null);
          setServerTimezone(fallbackTimezone);
          setServerCurrentDay(getCurrentDayInTimezone(fallbackTimezone.offset));
        }
      }
    };
    loadServerTimezone();
    return () => {
      cancelled = true;
    };
  }, []);

  // The backend resolves the special "latest" request to a concrete date.
  useEffect(() => {
    if (recordingPagination.date && recordingPagination.date !== chartDate) {
      setChartDate(recordingPagination.date);
    }
  }, [chartDate, recordingPagination.date]);

  // Select the busiest camera while preserving an existing valid selection.
  useEffect(() => {
    if (allCameraRows.length === 0) return;
    const busiest = allCameraRows.reduce((best, row) => (
      row.recordings.length > best.recordings.length ? row : best
    ), allCameraRows[0]);
    setSelectedCameraId((current) => {
      if (current && allCameraRows.some((row) => row.cameraId === current)) return current;
      return busiest.cameraId;
    });
  }, [allCameraRows.length, allCameraRows.map((row) => row.cameraId).join(',')]); // eslint-disable-line react-hooks/exhaustive-deps

  // Keep inline card playback stopped while expanded view is open.
  useEffect(() => {
    if (expandedContext) {
      stopInlineMediaPlayback();
      setPlayingId(null);
    }
  }, [expandedContext, stopInlineMediaPlayback]);

  // Stop inline playback as soon as the document begins moving vertically.
  useEffect(() => {
    if (!playingId) return undefined;

    const mainContent = document.querySelector('.main-content');
    const scrollTargets = mainContent ? [mainContent, window] : [window];
    let stopped = false;
    let touchStart = null;
    const stopPlayback = () => {
      if (stopped) return;
      stopped = true;
      stopInlineMediaPlayback();
      setPlayingId(null);
    };
    const handleWheel = (event) => {
      if (Math.abs(event.deltaY) > 0) stopPlayback();
    };
    const handleTouchStart = (event) => {
      const touch = event.touches?.[0];
      touchStart = touch ? { x: touch.clientX, y: touch.clientY } : null;
    };
    const handleTouchMove = (event) => {
      const touch = event.touches?.[0];
      if (!touchStart || !touch) return;
      const deltaX = touch.clientX - touchStart.x;
      const deltaY = touch.clientY - touchStart.y;
      if (Math.abs(deltaY) >= 4 && Math.abs(deltaY) > Math.abs(deltaX)) {
        stopPlayback();
      }
    };

    scrollTargets.forEach((target) => target.addEventListener('scroll', stopPlayback, { passive: true }));
    window.addEventListener('wheel', handleWheel, { passive: true });
    window.addEventListener('touchstart', handleTouchStart, { passive: true });
    window.addEventListener('touchmove', handleTouchMove, { passive: true });
    return () => {
      scrollTargets.forEach((target) => target.removeEventListener('scroll', stopPlayback));
      window.removeEventListener('wheel', handleWheel);
      window.removeEventListener('touchstart', handleTouchStart);
      window.removeEventListener('touchmove', handleTouchMove);
    };
  }, [playingId, stopInlineMediaPlayback]);

  // Clear delayed focus work when Event View unmounts.
  useEffect(() => () => {
    if (focusResetTimerRef.current) {
      clearTimeout(focusResetTimerRef.current);
    }
  }, []);

  const expandedRowRecordings = useMemo(
    () => (expandedContext
      ? filteredCameraRowsById[expandedContext.cameraId]?.recordings || []
      : []),
    [expandedContext, filteredCameraRowsById],
  );
  const expandedRecording = expandedContext
    ? expandedRowRecordings[expandedContext.index] || null
    : null;

  useEffect(() => {
    if (
      clipController
      && (!playbackMode.startsWith('webrtc-') || (!playingId && !expandedRecording))
    ) {
      clipController.stop().catch((error) => {
        if (!['CLIP_SESSION_CLOSED', 'CLIP_SESSION_REPLACED'].includes(error.code)) {
          console.warn('Failed to stop persistent clip playback:', error);
        }
      });
    }
  }, [clipController, expandedRecording, playbackMode, playingId]);
  const canNavigatePrev = !!expandedContext && expandedContext.index > 0;
  const canNavigateNext = !!expandedContext && expandedContext.index < (expandedRowRecordings.length - 1);
  const expandedPersonsState = expandedRecording
    ? personsByRecording[expandedRecording.id] || { loading: false, error: '', persons: [] }
    : { loading: false, error: '', persons: [] };
  const expandedPersons = expandedPersonsState.persons || [];
  const expandedPerson = expandedPersons[expandedPersonIndex] || null;

  useEffect(() => {
    if (!expandedRecording || expandedView !== 'people' || personsByRecording[expandedRecording.id]) {
      return undefined;
    }

    const recordingId = expandedRecording.id;
    setPersonsByRecording((current) => ({
      ...current,
      [recordingId]: { loading: true, error: '', persons: [] },
    }));
    api.getRecordingPersons(recordingId)
      .then((response) => {
        const persons = Array.isArray(response.data?.persons) ? response.data.persons : [];
        setPersonsByRecording((current) => ({
          ...current,
          [recordingId]: { loading: false, error: '', persons },
        }));
      })
      .catch((error) => {
        setPersonsByRecording((current) => ({
          ...current,
          [recordingId]: {
            loading: false,
            error: error?.response?.data?.detail || 'Unable to load person crops',
            persons: [],
          },
        }));
      });
    return undefined;
  }, [expandedRecording, expandedView, personsByRecording]);

  useEffect(() => {
    if (!expandedRecording || expandedView !== 'people') return undefined;
    const handleKeyDown = (event) => {
      if (event.key === 'Escape') {
        handleCloseExpanded();
      } else if (event.key === 'ArrowLeft') {
        setExpandedPersonIndex((index) => Math.max(0, index - 1));
      } else if (event.key === 'ArrowRight') {
        setExpandedPersonIndex((index) => Math.min(Math.max(0, expandedPersons.length - 1), index + 1));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [expandedRecording, expandedPersons.length, expandedView]);
  // Zone and metric filters have inline empty states. This page-level empty
  // state is reserved for the absence of completed recordings altogether.
  if (availableCompletedRecordings.length === 0 && recordingPagination.loading) {
    return (
      <div className="empty-reels-state">
        <span className="loading" aria-hidden="true" />
        <p>Loading recent events...</p>
      </div>
    );
  }

  if (availableCompletedRecordings.length === 0) {
    return (
      <div className="empty-reels-state">
        <Camera size={64} />
        <h3>No events on {chartDate}</h3>
        <p>Choose another date or wait for a recording to complete.</p>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <button
            type="button"
            className="btn btn-secondary"
            disabled={chartDate >= getTodayLocal()}
            onClick={() => shiftDate(1)}
          >
            Next day
          </button>
          <button
            type="button"
            className="btn btn-secondary"
            onClick={() => shiftDate(-1)}
          >
            Previous day
          </button>
        </div>
      </div>
    );
  }

  return (
    <>
      <div className="event-zone-page-header">
        <h2>Event Zone</h2>
        <div className="event-zone-timezone" title={serverTimezone?.source === 'backend' ? 'Backend timezone' : 'UTC fallback timezone'}>
          Time zone: {timezoneLabel}
        </div>
      </div>

      <div className="camera-rows">
        {allCameraRows.length === 0 && (
          <div style={{ padding: '32px 0', textAlign: 'center', color: '#78909c', fontSize: 13 }}>
            No recordings match current filters.
          </div>
        )}
        {/* Each camera row combines its event log, chart, and paged reel grid. */}
        {cameraRows.map((row) => {
          const totalPages = Math.max(1, Math.ceil(row.recordings.length / REELS_PER_PAGE));
          const currentPage = Math.min(pageByCam[row.cameraId] || 0, totalPages - 1);
          const pageStart = currentPage * REELS_PER_PAGE;
          const pageRecordings = row.recordings.slice(pageStart, pageStart + REELS_PER_PAGE);

          return (
            <div key={row.cameraId} className="camera-row-card">
              <div className="camera-row-header">
                <div className="camera-row-selector" role="radiogroup" aria-label="Camera">
                  {allCameraRows.map((cameraRow) => (
                    <label
                      key={cameraRow.cameraId}
                      className={`camera-selector-option${selectedCameraId === cameraRow.cameraId ? ' active' : ''}`}
                    >
                      <input
                        type="radio"
                        name="camera-selector"
                        value={cameraRow.cameraId}
                        checked={selectedCameraId === cameraRow.cameraId}
                        onChange={() => setSelectedCameraId(cameraRow.cameraId)}
                      />
                      <span>{cameraRow.cameraName}</span>
                      <small>{filteredCameraRowsById[cameraRow.cameraId]?.recordings.length || 0}</small>
                    </label>
                  ))}
                </div>
                <div className="camera-row-meta">
                  {liveMetricsByCamera[row.cameraId] && (
                    <span className="realtime-camera-metrics">
                      {Number(liveMetricsByCamera[row.cameraId].fps || 0).toFixed(1)} fps
                      {' · '}
                      {liveMetricsByCamera[row.cameraId].person_count ?? 0} people
                      {' · '}
                      activity {Number(
                        liveMetricsByCamera[row.cameraId].activity_percentage
                        ?? liveMetricsByCamera[row.cameraId].activity
                        ?? liveMetricsByCamera[row.cameraId].activity_ratio
                        ?? 0
                      ).toFixed(2)}
                    </span>
                  )}
                </div>
              </div>

              <EventLogBlock
                row={row}
                chartDate={chartDate}
                highlightedRecordingId={highlightedRecordingId}
                markedIds={markedIds}
                onToggleMark={handleToggleMark}
                showMarkedOnly={showMarkedOnly}
                setShowMarkedOnly={setShowMarkedOnly}
                markedCount={markedCount}
                showAllEvents={showAllEvents}
                setShowAllEvents={setShowAllEvents}
                getTodayLocal={getTodayLocal}
                shiftDate={shiftDate}
                timezoneOffset={timezoneOffset}
                MOTION_COLORS={MOTION_COLORS}
                onLogClick={handleTimelinePointClick}
              />

              <ChartCard 
                row={row}
                chartDate={chartDate}
                handleTimelinePointClick={handleTimelinePointClick}
                highlightedRecordingId={highlightedRecordingId}
                chartToggles={chartToggles}
                setChartToggles={setChartToggles}
                timezoneOffset={timezoneOffset}
                MOTION_COLORS={MOTION_COLORS}
              />

              {/* A page contains at most 25 reels arranged as five columns by five rows. */}
              <div className="reels-carousel-wrapper">
                <div
                  className="reels-grid row-grid"
                  ref={(el) => {
                    rowScrollRefs.current[row.cameraId] = el;
                  }}
                >
                  {pageRecordings.map((recording, recordingIndex) => (
                          <ReelCard
                            key={recording.id}
                            recording={recording}
                            recordingIndex={pageStart + recordingIndex}
                            row={row}
                            playingId={playingId}
                            expandedContext={expandedContext}
                            playbackStatsById={playbackStatsById}
                            playbackMode={playbackMode}
                            clipController={clipController}
                            allowHttpFallback={allowedPlaybackModes.includes('file')}
                            highlightedRecordingId={highlightedRecordingId}
                            focusedRecordingId={focusedRecordingId}
                            labelMap={markedIds}
                            overlayIds={overlayIds}
                            MOTION_COLORS={MOTION_COLORS}
                            videoRefs={videoRefs}
                            reelCardRefs={reelCardRefs}
                            handleClick={handleClick}
                            handleOpenExpanded={handleOpenExpanded}
                            handleVideoTimeUpdate={handleVideoTimeUpdate}
                            handleVideoLoadedMetadata={handleVideoLoadedMetadata}
                            handleVideoEnded={handleVideoEnded}
                            handleSeekStart={handleSeekStart}
                            handleSeekEnd={handleSeekEnd}
                            handleSeekChange={handleSeekChange}
                            handleDownloadRecording={downloadRecordingFile}
                            handleDeleteRecording={handleDeleteRecording}
                            onToggleMark={handleToggleMark}
                            timezoneOffset={timezoneOffset}
                            timezoneName={serverTimezone?.name || ''}
                          />
                  ))}
                </div>

                {totalPages > 1 && (
                  <div className="reel-page-controls" aria-label={`${row.cameraName} reel pages`}>
                    <button
                      type="button"
                      className="btn btn-secondary reel-page-button"
                      disabled={currentPage === 0}
                      onClick={() => changeReelPage(row.cameraId, currentPage - 1, totalPages)}
                    >
                      <ChevronLeft size={16} />
                      Previous
                    </button>
                    <span className="reel-page-status">
                      Page {currentPage + 1} of {totalPages}
                    </span>
                    <button
                      type="button"
                      className="btn btn-secondary reel-page-button"
                      disabled={currentPage >= totalPages - 1}
                      onClick={() => changeReelPage(row.cameraId, currentPage + 1, totalPages)}
                    >
                      Next
                      <ChevronRight size={16} />
                    </button>
                  </div>
                )}
              </div>

              {onvifEventsEnabled && (
                <OnvifEventBlock
                  row={row}
                  events={onvifEventsByCamera[row.cameraId] || []}
                  listenerStatus={onvifListenerByCamera[row.cameraId] || null}
                  loading={Boolean(onvifLoadingByCamera[row.cameraId])}
                  error={onvifErrorByCamera[row.cameraId] || ''}
                  timezoneOffset={timezoneOffset}
                  onRefresh={() => loadOnvifEvents(row.cameraId, false)}
                />
              )}
            </div>
          );
        })}
      </div>

      {(recordingPagination.hasMore || recordingPagination.loading || recordingPagination.error) && (
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: 12, margin: '18px 0' }}>
          {recordingPagination.error ? (
            <span className="api-endpoint-error">{recordingPagination.error}</span>
          ) : null}
          {recordingPagination.hasMore && (
            <button
              type="button"
              className="btn btn-secondary"
              disabled={recordingPagination.loading}
              onClick={() => onLoadMoreRecordings?.().catch((error) => {
                console.error('Failed to load older events:', error);
              })}
            >
              {recordingPagination.loading
                ? 'Loading...'
                : `Load older events (${recordingPagination.loaded}/${recordingPagination.total})`}
            </button>
          )}
        </div>
      )}

      {expandedRecording && createPortal((
        /* === Expanded Modal View === 
           Full-screen modal for focused reel playback with navigation */
        <div
          className={`enlarged-overlay${document.querySelector('.app.theme-dark') ? ' theme-dark' : ''}`}
          onClick={handleCloseExpanded}
        >
          <div className="enlarged-content" onClick={(event) => event.stopPropagation()}>
            <div className="enlarged-card-stage">
              <div className="reel-card enlarged-reel-card">
                <div className="enlarged-reel-header">
                  <span className="enlarged-title">{expandedRecording.filename || expandedRecording.id}</span>
                  <div className="enlarged-view-tabs" role="tablist" aria-label="Clip details">
                    <button
                      type="button"
                      role="tab"
                      aria-selected={expandedView === 'video'}
                      className={expandedView === 'video' ? 'active' : ''}
                      onClick={() => setExpandedView('video')}
                    >
                      Video
                    </button>
                    {Number(getRecordingMetadata(expandedRecording).person_crop_count || 0) > 0 && (
                      <button
                        type="button"
                        role="tab"
                        aria-selected={expandedView === 'people'}
                        className={expandedView === 'people' ? 'active' : ''}
                        onClick={() => {
                          setExpandedPersonIndex(0);
                          setExpandedView('people');
                        }}
                      >
                        People ({Number(getRecordingMetadata(expandedRecording).person_crop_count || 0)})
                      </button>
                    )}
                  </div>
                  <button
                    type="button"
                    className="enlarged-close"
                    onClick={handleCloseExpanded}
                    title="Close enlarged playback"
                  >
                    <X size={16} />
                  </button>
                </div>
                {(() => {
                  const {
                    timestampParts,
                    playbackStats,
                    playbackDuration,
                    playbackProgress,
                    playbackFrame,
                    totalFrames,
                  } = getRecordingPlaybackViewData(
                    expandedRecording,
                    playbackStatsById[expandedRecording.id],
                    timezoneOffset,
                  );

                  return (
                    <>
                      <div className="reel-timestamp">
                        <span className="reel-date">{timestampParts.date}</span>
                        {timestampParts.time && <span className="reel-time">{timestampParts.time}</span>}
                      </div>

                      {expandedView === 'video' ? (
                      <>
                      <div className="reel-thumbnail">
                        <button
                          type="button"
                          className="enlarged-inline-nav prev"
                          disabled={!canNavigatePrev}
                          onClick={(event) => {
                            event.stopPropagation();
                            handleExpandedNavigate(-1);
                          }}
                          title="Previous"
                        >
                          <ChevronLeft size={20} />
                        </button>

                        {playbackMode === 'file' ? (
                          <video
                            ref={(el) => (expandedVideoRefs.current[expandedRecording.id] = el)}
                            className="reel-video"
                            src={api.getRecordingStreamUrl(
                              expandedRecording.id,
                              !!overlayIds[expandedRecording.id],
                            )}
                            loop={false}
                            playsInline
                            controls
                            autoPlay
                            onLoadedMetadata={(event) => handleVideoLoadedMetadata(expandedRecording.id, event)}
                            onTimeUpdate={(event) => handleVideoTimeUpdate(expandedRecording.id, event)}
                            onError={() => showRecordingPlaybackLimitToast(expandedRecording.id)}
                          />
                        ) : (
                          <RecordedWebRTCPlayer
                            recordingId={expandedRecording.id}
                            mode={playbackMode}
                            clipController={clipController}
                            active
                            overlay={!!overlayIds[expandedRecording.id]}
                            allowHttpFallback={allowedPlaybackModes.includes('file')}
                            controls
                            setVideoRef={(element) => {
                              expandedVideoRefs.current[expandedRecording.id] = element;
                            }}
                          />
                        )}

                        <button
                          type="button"
                          className="enlarged-inline-nav next"
                          disabled={!canNavigateNext}
                          onClick={(event) => {
                            event.stopPropagation();
                            handleExpandedNavigate(1);
                          }}
                          title="Next"
                        >
                          <ChevronRight size={20} />
                        </button>
                      </div>

                      <div className="reel-info">
                        <div className="enlarged-ai-action">
                          <span>AI overlay</span>
                          <OverlayButton
                            recording={expandedRecording}
                            overlayIds={overlayIds}
                            setOverlayIds={setOverlayIds}
                            videoRefs={expandedVideoRefs}
                          />
                        </div>
                        <div className="reel-playback-controls">
                          <div className="reel-progress-header">
                            <div className="reel-progress-left">
                              <TimeFrameBadge timeText={formatPlaybackTime(playbackStats.currentTime)} frame={playbackFrame} />
                            </div>
                            <FrameStepButtons
                              disabled={playbackMode !== 'file'}
                              onStepBack={(event) => {
                                event.stopPropagation();
                                stepFrame(expandedRecording, -1, true);
                              }}
                              onStepForward={(event) => {
                                event.stopPropagation();
                                stepFrame(expandedRecording, 1, true);
                              }}
                            />
                            <div className="reel-progress-right">
                              <TimeFrameBadge timeText={formatPlaybackTime(playbackDuration)} frame={totalFrames} />
                            </div>
                          </div>
                          <input
                            type="range"
                            min={0}
                            max={Math.max(playbackDuration, 0.01)}
                            step={0.01}
                            value={Math.min(playbackStats.currentTime, Math.max(playbackDuration, 0.01))}
                            disabled={playbackMode !== 'file'}
                            onMouseDown={() => handleSeekStart(expandedRecording.id, true)}
                            onMouseUp={() => handleSeekEnd(expandedRecording.id)}
                            onTouchStart={() => handleSeekStart(expandedRecording.id, true)}
                            onTouchEnd={() => handleSeekEnd(expandedRecording.id)}
                            onChange={(event) => handleSeekChange(expandedRecording.id, event.target.value, true)}
                            className="reel-progress-slider"
                            style={{ '--progress': `${playbackProgress}%` }}
                          />
                          <SimpleMotionPlot recording={expandedRecording} MOTION_COLORS={MOTION_COLORS} />
                        </div>
                      </div>
                      </>
                      ) : (
                        <div className="enlarged-people-view">
                          {expandedPersonsState.loading ? (
                            <div className="enlarged-people-state">
                              <Loader size={24} className="spin-icon" />
                              <span>Loading person crops…</span>
                            </div>
                          ) : expandedPersonsState.error ? (
                            <div className="enlarged-people-state error">
                              <span>{expandedPersonsState.error}</span>
                              <button
                                type="button"
                                className="btn btn-secondary"
                                onClick={() => setPersonsByRecording((current) => {
                                  const next = { ...current };
                                  delete next[expandedRecording.id];
                                  return next;
                                })}
                              >
                                Retry
                              </button>
                            </div>
                          ) : expandedPerson ? (
                            <>
                              <div
                                className="enlarged-person-stage"
                                onTouchStart={(event) => {
                                  personSwipeStartRef.current = event.touches[0]?.clientX ?? null;
                                }}
                                onTouchEnd={(event) => {
                                  const startX = personSwipeStartRef.current;
                                  const endX = event.changedTouches[0]?.clientX;
                                  personSwipeStartRef.current = null;
                                  if (startX == null || endX == null || Math.abs(endX - startX) < 45) return;
                                  const direction = endX < startX ? 1 : -1;
                                  setExpandedPersonIndex((index) => Math.max(
                                    0,
                                    Math.min(expandedPersons.length - 1, index + direction),
                                  ));
                                }}
                              >
                                <button
                                  type="button"
                                  className="enlarged-inline-nav prev"
                                  disabled={expandedPersonIndex === 0}
                                  onClick={() => setExpandedPersonIndex((index) => Math.max(0, index - 1))}
                                  title="Previous person"
                                  aria-label="Previous person"
                                >
                                  <ChevronLeft size={20} />
                                </button>
                                <img
                                  key={`${expandedRecording.id}-${expandedPerson.pid}`}
                                  src={api.getPersonImageUrl(expandedRecording.id, expandedPerson.pid)}
                                  alt={`Person ${expandedPersonIndex + 1} from this clip`}
                                />
                                <button
                                  type="button"
                                  className="enlarged-inline-nav next"
                                  disabled={expandedPersonIndex >= expandedPersons.length - 1}
                                  onClick={() => setExpandedPersonIndex((index) => Math.min(expandedPersons.length - 1, index + 1))}
                                  title="Next person"
                                  aria-label="Next person"
                                >
                                  <ChevronRight size={20} />
                                </button>
                              </div>
                              <div className="enlarged-person-caption">
                                <strong>Person {expandedPersonIndex + 1} of {expandedPersons.length}</strong>
                                <span>Track ID {expandedPerson.pid}</span>
                              </div>
                              {expandedPersons.length > 1 && (
                                <div className="enlarged-person-strip" aria-label="People in this clip">
                                  {expandedPersons.map((person, index) => (
                                    <button
                                      type="button"
                                      key={person.id || person.pid}
                                      className={index === expandedPersonIndex ? 'active' : ''}
                                      onClick={() => setExpandedPersonIndex(index)}
                                      aria-label={`Show person ${index + 1}`}
                                    >
                                      <img
                                        src={api.getPersonImageUrl(expandedRecording.id, person.pid)}
                                        alt=""
                                        loading={Math.abs(index - expandedPersonIndex) <= 1 ? 'eager' : 'lazy'}
                                      />
                                    </button>
                                  ))}
                                </div>
                              )}
                            </>
                          ) : (
                            <div className="enlarged-people-state">
                              No person images are available for this clip.
                            </div>
                          )}
                        </div>
                      )}
                    </>
                  );
                })()}
              </div>
            </div>
          </div>
        </div>
      ), document.body)}
    </>
  );
};

export default EventView;
