import { transportApi } from './api';

export const waitForIceGathering = (
  peer,
  timeoutMs = 5000,
  startedAt = performance.now(),
) => new Promise((resolve) => {
  let timeout;
  const finish = (complete) => {
    if (timeout) window.clearTimeout(timeout);
    peer.removeEventListener('icegatheringstatechange', onStateChange);
    resolve({
      complete,
      elapsedMs: Math.round(performance.now() - startedAt),
    });
  };
  const onStateChange = () => {
    if (peer.iceGatheringState === 'complete') finish(true);
  };
  if (peer.iceGatheringState === 'complete') {
    finish(true);
    return;
  }
  peer.addEventListener('icegatheringstatechange', onStateChange);
  timeout = window.setTimeout(() => finish(false), timeoutMs);
});

export const buildIceServers = (config, turnOnly = false) => {
  if (turnOnly) {
    if (!config.turn_urls?.length) throw new Error('TURN is not configured on the server');
    return [{
      urls: config.turn_urls,
      username: config.turn_username || undefined,
      credential: config.turn_credential || undefined,
    }];
  }
  const servers = [];
  if (config.stun_urls?.length) servers.push({ urls: config.stun_urls });
  if (config.turn_urls?.length) {
    servers.push({
      urls: config.turn_urls,
      username: config.turn_username || undefined,
      credential: config.turn_credential || undefined,
    });
  }
  return servers;
};

export const preferH264 = (transceiver) => {
  const capabilities = window.RTCRtpReceiver?.getCapabilities?.('video');
  if (!capabilities || typeof transceiver.setCodecPreferences !== 'function') return;
  const h264 = capabilities.codecs.filter(
    (codec) => codec.mimeType.toLowerCase() === 'video/h264',
  );
  const others = capabilities.codecs.filter(
    (codec) => codec.mimeType.toLowerCase() !== 'video/h264',
  );
  if (h264.length) transceiver.setCodecPreferences([...h264, ...others]);
};

export const createReceivePeer = async ({ audio = false, turnOnly = false } = {}) => {
  const config = await transportApi.getIceConfig();
  const peer = new RTCPeerConnection({
    iceServers: buildIceServers(config, turnOnly),
    iceTransportPolicy: turnOnly ? 'relay' : 'all',
  });
  const videoTransceiver = peer.addTransceiver('video', { direction: 'recvonly' });
  preferH264(videoTransceiver);
  if (audio) peer.addTransceiver('audio', { direction: 'recvonly' });
  return peer;
};
