export const RecordingMetaInfo = ({
  personValue,
  durationText,
  activityValue,
  changeValue,
  loiteringValue,
  burglaryValue,
  fightValue,
  doorEventsValue,
  soundLabelValue,
  velValue,
  MOTION_COLORS = {},
}) => {
  const formatNum = (value, digits = 2) => {
    const n = Number(value);
    return Number.isFinite(n) ? n.toFixed(digits) : 'N/A';
  };
  const formatScorePercent = (value) => {
    const n = Number(value);
    if (!Number.isFinite(n)) return undefined;
    return `${Math.max(0, Math.min(100, Math.round(n * 100)))}%`;
  };
  const formatScoreOutOfFive = (value) => {
    const n = Number(value);
    return Number.isFinite(n) ? `${Math.max(0, Math.min(5, Math.round(n * 5)))}/5` : 'N/A';
  };

  // Derive alert color from "[alert:N]" suffix in label string
  const alertColor = (label) => {
    if (!label) return MOTION_COLORS.loudness || '#ff9800';
    const m = label.match(/\[alert:(\d+)\]/);
    const score = m ? parseInt(m[1], 10) : -1;
    if (score >= 3) return '#c62828';
    if (score === 2) return '#ef6c00';
    if (score === 1) return '#f9a825';
    return '#66bb6a';
  };

  const soundDisplay = soundLabelValue
    ? soundLabelValue.replace(/\s*\[alert:\d+\]/, '').replace(/\s*\[confidence:[^\]]+\]/, '')
    : 'N/A';

  // Summarise door_events. New recordings store one best status string;
  // older recordings may still have an array of full event objects.
  const doorSummary = (() => {
    if (typeof doorEventsValue === 'string') {
      if (!doorEventsValue) return null;
      const labels = {
        entry: 'In',
        exit: 'Out',
        'walk-across': 'Across',
        unknown: '?',
      };
      return { text: labels[doorEventsValue] || doorEventsValue, tooltip: doorEventsValue };
    }
    if (!Array.isArray(doorEventsValue) || doorEventsValue.length === 0) return null;
    const counts = { entry: 0, exit: 0, 'walk-across': 0, unknown: 0 };
    doorEventsValue.forEach((ev) => { counts[ev.status] = (counts[ev.status] || 0) + 1; });
    const parts = [];
    if (counts.entry)      parts.push(`${counts.entry}↑`);
    if (counts.exit)       parts.push(`${counts.exit}↓`);
    if (counts['walk-across']) parts.push(`${counts['walk-across']}→`);
    if (counts.unknown)    parts.push(`${counts.unknown}?`);
    const tooltip = doorEventsValue
      .map((ev) => `pid ${ev.pid}: ${ev.status} (traj ${ev.traj_dir}° / entry ${ev.entry_dir}°)`)
      .join('\n');
    return { text: parts.join(' '), tooltip };
  })();

  const chips = [
    { label: 'Person', value: personValue != null ? String(personValue) : 'N/A', color: MOTION_COLORS.person || '#8e24aa' },
    { label: 'Duration', value: durationText, color: MOTION_COLORS.duration || '#e91e63' },
    { label: 'Activity', value: formatNum(activityValue), color: MOTION_COLORS.activity || '#009688' },
    { label: 'Change', value: formatNum(changeValue, 1), color: MOTION_COLORS.change || '#5c6bc0' },
    { label: 'Loiter', value: formatNum(loiteringValue), color: MOTION_COLORS.loitering || '#2e7d32' },
    { label: 'Burglary', value: formatScoreOutOfFive(burglaryValue), color: MOTION_COLORS.burglary || '#ef6c00', title: formatScorePercent(burglaryValue) },
    { label: 'Fight', value: formatScoreOutOfFive(fightValue), color: MOTION_COLORS.fight || '#c62828', title: formatScorePercent(fightValue) },
    doorSummary && { label: 'Door', value: doorSummary.text, color: '#7c4700', title: doorSummary.tooltip },
    { label: 'Sound', value: soundDisplay, color: alertColor(soundLabelValue) },
    { label: 'Vel', value: formatNum(velValue), color: '#00897b' },
  ].filter(Boolean);

  return (
    <div className="recording-meta">
      {chips.map((chip) => (
        <div key={chip.label} className="meta-item" title={chip.title}>
          <span style={{ color: chip.color, fontWeight: 700 }}>{chip.label}:</span>
          <span style={{ color: chip.color }}>{chip.value}</span>
        </div>
      ))}
    </div>
  );
};

export const getRecordingMetadata = (recording) => {
  const metadata = recording?.metadata;
  if (!metadata) return {};

  if (typeof metadata === 'string') {
    try {
      return JSON.parse(metadata);
    } catch (_error) {
      return {};
    }
  }

  return typeof metadata === 'object' ? metadata : {};
};

export const DEFAULT_TIMEZONE_OFFSET = '+00:00';

/** Return a recording timestamp as a YYYY-MM-DD date string in the selected timezone. */
export const getRecordingLocalDate = (recording, timezoneOffset = DEFAULT_TIMEZONE_OFFSET) => {
  const metadata = getRecordingMetadata(recording);
  const timestamp = metadata?.time_stamp
    || metadata?.timestamp
    || recording?.start_time
    || recording?.started_at
    || recording?.created_at;
  if (!timestamp) return null;

  return formatDateKeyInTimezone(timestamp, timezoneOffset);
};

/** Return the current day in the selected timezone as YYYY-MM-DD. */
export const getCurrentDayInTimezone = (timezoneOffset = DEFAULT_TIMEZONE_OFFSET) => {
  return formatDateKeyInTimezone(new Date(), timezoneOffset);
};

/** Shift a YYYY-MM-DD date by the requested number of calendar days. */
export const shiftLocalDate = (dateString, dayDelta) => {
  const [year, month, day] = String(dateString).split('-').map(Number);
  const value = new Date(Date.UTC(year, month - 1, day + dayDelta));
  const shiftedYear = value.getUTCFullYear();
  const shiftedMonth = String(value.getUTCMonth() + 1).padStart(2, '0');
  const shiftedDay = String(value.getUTCDate()).padStart(2, '0');
  return `${shiftedYear}-${shiftedMonth}-${shiftedDay}`;
};

/** Return whether a recording passes at least one enabled chart metric filter. */
export const recordingMatchesMetricFilters = (recording, toggles = {}, thresholds = {}) => {
  const metadata = getRecordingMetadata(recording);
  const checks = [];
  const metrics = {
    person: getRecordingPersonCount(recording),
    duration: Number(metadata.duration ?? recording.duration ?? 0),
    activity: Number(metadata.activity ?? metadata.activity_percentage ?? 0),
    change: getRecordingChangeValue(recording),
    loitering: Number(metadata.loitering_score ?? 0),
    burglary: Number(metadata.burglary_score ?? 0),
    fight: Number(metadata.fight_score ?? 0),
    audio: Number(metadata.sound_alert ?? -1),
  };

  Object.keys(metrics).forEach((key) => {
    if (toggles[key]) {
      checks.push(metrics[key] >= Number(thresholds[key] || 0));
    }
  });

  return checks.length === 0 || checks.some(Boolean);
};

export const getRecordingPersonCount = (recording) => {
  const metadata = getRecordingMetadata(recording);
  const value = Number(metadata.max_person_count ?? metadata.person_count ?? 0);
  return Number.isFinite(value) ? Math.max(0, value) : 0;
};

export const getRecordingChangeValue = (recording) => {
  const metadata = getRecordingMetadata(recording);
  const changeDetection = metadata.change_detection;

  // A clip-level background-difference average is not a scene-change event.
  // Only report a percentage when change detection also produced image
  // evidence and attached its metadata to this recording.
  if (!changeDetection || typeof changeDetection !== 'object') return 0;

  const changedPercent = Number(changeDetection.changed_percent);
  if (Number.isFinite(changedPercent) && changedPercent > 0) {
    return Math.max(0, Math.min(100, changedPercent));
  }

  const percentValue = Number(changeDetection.percent ?? changeDetection.score);
  if (Number.isFinite(percentValue) && percentValue > 0) {
    return Math.max(0, percentValue <= 1 ? percentValue * 100 : percentValue);
  }

  return 0;
};

export const getTopSoundLabel = (metadata = {}) => {
  const labels = Array.isArray(metadata.sound_labels) ? metadata.sound_labels : [];
  const best = labels
    .filter((item) => item && typeof item === 'object')
    .sort((a, b) => Number(b.score ?? 0) - Number(a.score ?? 0))[0];

  if (best) {
    return {
      label: String(best.label || '').trim(),
      score: Number(best.score ?? 0),
      loudness: Number(best.loudness ?? 0),
      alert: Number(best.alert ?? metadata.sound_alert ?? -1),
    };
  }

  const fallbackLabel = String(metadata.sound_label || '').trim();
  if (!fallbackLabel) return null;
  return {
    label: fallbackLabel,
    score: null,
    loudness: Number(metadata.loudness ?? 0),
    alert: Number(metadata.sound_alert ?? -1),
  };
};

export const recordingHasDefaultEventSignal = (recording) => {
  const metadata = getRecordingMetadata(recording);
  const motionDiff = Number(metadata.diff ?? 0);
  return getRecordingPersonCount(recording) > 0
    || getRecordingChangeValue(recording) > 0
    || (Number.isFinite(motionDiff) && motionDiff > 0);
};

/** Trigger a browser download for a recording file. */
export const downloadRecordingFile = (recordingId) => {
  const link = document.createElement('a');
  link.href = api.downloadRecording(recordingId);
  link.download = '';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

export const formatTimestampParts = (value) => {
  return formatTimestampPartsWithServerTz(value, DEFAULT_TIMEZONE_OFFSET);
};

/**
 * Parse a timezone offset string like "+05:30" or "-08:00"
 * @param {string} offsetStr - Timezone offset string (e.g., "+05:30", "-08:00")
 * @returns {number} Offset in milliseconds
 */
export const parseTimezoneOffset = (offsetStr) => {
  if (!offsetStr || typeof offsetStr !== 'string') return 0;
  const match = offsetStr.match(/([+-])(\d{2}):(\d{2})/);
  if (!match) return 0;
  const sign = match[1] === '+' ? 1 : -1;
  const hours = parseInt(match[2], 10);
  const minutes = parseInt(match[3], 10);
  return sign * (hours * 60 + minutes) * 60 * 1000;
};

export const normalizeTimezone = (timezone) => {
  const offset = typeof timezone?.offset === 'string' && /^[-+]\d{2}:\d{2}$/.test(timezone.offset)
    ? timezone.offset
    : DEFAULT_TIMEZONE_OFFSET;
  return {
    name: timezone?.name || 'UTC',
    offset,
    current_time: timezone?.current_time || null,
    current_day: timezone?.current_day || getCurrentDayInTimezone(offset),
    current_time_formatted: timezone?.current_time_formatted || '',
    source: timezone ? 'backend' : 'fallback',
  };
};

/** Parse timezone-less backend timestamps as local to the server, not the browser. */
export const parseTimestampInTimezone = (value, timezoneOffset = DEFAULT_TIMEZONE_OFFSET) => {
  if (value instanceof Date) return new Date(value.getTime());
  if (typeof value === 'number') return new Date(value);

  const rawValue = String(value ?? '').trim();
  if (!rawValue) return null;

  const hasTime = /[T ]\d{2}:\d{2}/.test(rawValue);
  const hasTimezone = /(?:Z|[+-]\d{2}:?\d{2})$/i.test(rawValue);
  const normalizedValue = hasTime && !hasTimezone
    ? `${rawValue}${timezoneOffset}`
    : rawValue;
  const parsed = new Date(normalizedValue);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
};

const toTimezoneDate = (value, timezoneOffset = DEFAULT_TIMEZONE_OFFSET) => {
  const parsed = parseTimestampInTimezone(value, timezoneOffset);
  if (!parsed) return null;
  if (Number.isNaN(parsed.getTime())) return null;
  return new Date(parsed.getTime() + parseTimezoneOffset(timezoneOffset));
};

export const formatDateKeyInTimezone = (value, timezoneOffset = DEFAULT_TIMEZONE_OFFSET) => {
  const adjustedDate = toTimezoneDate(value, timezoneOffset);
  if (!adjustedDate) return null;
  const year = adjustedDate.getUTCFullYear();
  const month = String(adjustedDate.getUTCMonth() + 1).padStart(2, '0');
  const day = String(adjustedDate.getUTCDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

export const formatTimeInTimezone = (value, timezoneOffset = DEFAULT_TIMEZONE_OFFSET, includeSeconds = false) => {
  const adjustedDate = toTimezoneDate(value, timezoneOffset);
  if (!adjustedDate) return '';
  const hour = String(adjustedDate.getUTCHours()).padStart(2, '0');
  const minute = String(adjustedDate.getUTCMinutes()).padStart(2, '0');
  if (!includeSeconds) return `${hour}:${minute}`;
  const second = String(adjustedDate.getUTCSeconds()).padStart(2, '0');
  return `${hour}:${minute}:${second}`;
};

/**
 * Format timestamp using server timezone
 * @param {string|number|Date} value - The timestamp value
 * @param {string} timezoneOffset - Timezone offset like "+05:30" or "-08:00"
 * @returns {{date: string, time: string}} Formatted date and time parts
 */
export const formatTimestampPartsWithServerTz = (value, timezoneOffset = DEFAULT_TIMEZONE_OFFSET) => {
  if (!value) {
    return { date: 'N/A', time: '' };
  }

  const adjustedDate = toTimezoneDate(value, timezoneOffset);
  if (!adjustedDate) {
    return { date: String(value), time: '' };
  }

  return {
    date: adjustedDate.toLocaleDateString(undefined, { day: '2-digit', month: 'short', timeZone: 'UTC' }),
    time: adjustedDate.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit', timeZone: 'UTC' }),
  };
};

export const formatLongDateWithTimezone = (
  value,
  timezoneOffset = DEFAULT_TIMEZONE_OFFSET,
  timezoneName = '',
) => {
  const adjustedDate = toTimezoneDate(value, timezoneOffset);
  if (!adjustedDate) return 'N/A';

  const dateText = adjustedDate.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    timeZone: 'UTC',
  });

  let timezoneText = String(timezoneName || '').trim();
  if (/^(asia\/tokyo|japan|tokyo)$/i.test(timezoneText)) {
    timezoneText = 'JST';
  }
  if (!/^[A-Z]{2,6}$/.test(timezoneText)) {
    try {
      timezoneText = new Intl.DateTimeFormat('en-US', {
        timeZone: timezoneText || 'UTC',
        timeZoneName: 'short',
      }).formatToParts(parseTimestampInTimezone(value, timezoneOffset))
        .find((part) => part.type === 'timeZoneName')?.value || '';
    } catch (_error) {
      timezoneText = '';
    }
  }
  if (!timezoneText) {
    timezoneText = timezoneOffset === '+00:00' ? 'UTC' : `UTC${timezoneOffset}`;
  }

  return `${dateText} (${timezoneText})`;
};

/**
 * Get current day in server timezone
 * @param {string} timezoneOffset - Timezone offset like "+05:30" or "-08:00"
 * @returns {string} Current day in YYYY-MM-DD format
 */
export const getCurrentDayInServerTz = getCurrentDayInTimezone;

/**
 * Format a date/time using server timezone
 * @param {number|string|Date} value - Unix timestamp (seconds), ISO string, or Date object
 * @param {string} timezoneOffset - Timezone offset like "+05:30" or "-08:00"
 * @param {string} format - Format type: 'time', 'date', 'datetime', 'full'
 * @returns {string} Formatted date/time string
 */
export const formatWithServerTz = (value, timezoneOffset = DEFAULT_TIMEZONE_OFFSET, format = 'datetime') => {
  if (!value) return '';
  
  let date;
  if (typeof value === 'number') {
    // Assume Unix timestamp in seconds (common for chart data)
    date = new Date(value * 1000);
  } else if (typeof value === 'string') {
    date = new Date(value);
  } else if (value instanceof Date) {
    date = new Date(value.getTime());
  } else {
    return '';
  }

  if (Number.isNaN(date.getTime())) return '';

  const adjustedDate = toTimezoneDate(date, timezoneOffset);
  if (!adjustedDate) return '';

  switch (format) {
    case 'time':
      return formatTimeInTimezone(adjustedDate, DEFAULT_TIMEZONE_OFFSET);
    case 'time-full':
      return formatTimeInTimezone(adjustedDate, DEFAULT_TIMEZONE_OFFSET, true);
    case 'date':
      return formatDateKeyInTimezone(adjustedDate, DEFAULT_TIMEZONE_OFFSET);
    case 'datetime':
      return `${formatDateKeyInTimezone(adjustedDate, DEFAULT_TIMEZONE_OFFSET)} ${formatTimeInTimezone(adjustedDate, DEFAULT_TIMEZONE_OFFSET, true)}`;
    case 'full':
      return adjustedDate.toLocaleString(undefined, {
        year: 'numeric',
        month: 'short',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false,
        timeZone: 'UTC',
      });
    default:
      return `${formatDateKeyInTimezone(adjustedDate, DEFAULT_TIMEZONE_OFFSET)} ${formatTimeInTimezone(adjustedDate, DEFAULT_TIMEZONE_OFFSET, true)}`;
  }
};

/**
 * Format time for chart x-axis (HH:MM format)
 * @param {number} ts - Unix timestamp in seconds
 * @param {string} timezoneOffset - Timezone offset like "+05:30" or "-08:00"
 * @returns {string} Time string in HH:MM format
 */
export const formatChartTime = (ts, timezoneOffset = DEFAULT_TIMEZONE_OFFSET) => {
  if (!ts) return '--:--';
  return formatTimeInTimezone(new Date(ts * 1000), timezoneOffset);
};

export const formatDuration = (value) => {
  const numericValue = Number(value);
  if (Number.isFinite(numericValue)) {
    const totalSeconds = Math.max(0, Math.round(numericValue));
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}m ${seconds}s`;
  }
  return 'N/A';
};

export const formatPlaybackTime = (value) => {
  const numericValue = Number(value);
  if (!Number.isFinite(numericValue) || numericValue < 0) {
    return '00:00.00';
  }
  const totalSeconds = Math.floor(numericValue);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  const centiseconds = Math.floor((numericValue - totalSeconds) * 100);
  return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${centiseconds.toString().padStart(2, '0')}`;
};

export const resolvePlaybackFps = (recording, metadata) => {
  const fpsFromRecording = Number(recording?.fps);
  if (Number.isFinite(fpsFromRecording) && fpsFromRecording > 0) {
    return fpsFromRecording;
  }

  const fpsFromMetadata = Number(metadata?.fps);
  if (Number.isFinite(fpsFromMetadata) && fpsFromMetadata > 0) {
    return fpsFromMetadata;
  }

  return 30;
};

export const getRecordingTimestampValue = (recording, metadata) => (
  metadata?.time_stamp
  || metadata?.timestamp
  || recording?.start_time
  || recording?.started_at
  || recording?.created_at
  || null
);

export const getRecordingPlaybackViewData = (
  recording,
  playbackStatsInput,
  timezoneOffset = DEFAULT_TIMEZONE_OFFSET,
) => {
  const metadata = getRecordingMetadata(recording);
  const timestampValue = getRecordingTimestampValue(recording, metadata);
  const timestampParts = formatTimestampPartsWithServerTz(timestampValue, timezoneOffset);
  const durationValue = metadata.duration ?? recording?.duration;
  const velValue = metadata.vel;
  const loudnessValue = metadata.loudness ?? null;
  const topSound = getTopSoundLabel(metadata);
  const soundLabelValue = topSound?.label || null;
  const personValue = getRecordingPersonCount(recording);
  const activityValue = metadata.activity ?? metadata.activity_percentage ?? null;
  const changeValue = getRecordingChangeValue(recording);
  const loiteringValue = metadata.loitering_score ?? null;
  const burglaryValue = metadata.burglary_score ?? null;
  const fightValue = metadata.fight_score ?? null;
  const doorEventsValue = Array.isArray(metadata.door_events) || typeof metadata.door_events === 'string'
    ? metadata.door_events
    : null;

  const playbackStats = playbackStatsInput || { currentTime: 0, duration: 0 };
  const playbackDuration = playbackStats.duration > 0
    ? playbackStats.duration
    : (Number(recording?.duration) || 0);
  const playbackProgress = playbackDuration > 0
    ? Math.min(100, Math.max(0, (playbackStats.currentTime / playbackDuration) * 100))
    : 0;
  const playbackFps = resolvePlaybackFps(recording, metadata);
  const playbackFrame = Math.max(0, Math.floor(playbackStats.currentTime * playbackFps));
  const totalFrames = Math.max(0, Math.floor(playbackDuration * playbackFps));

  return {
    metadata,
    timestampParts,
    durationValue,
    velValue,
    loudnessValue,
    soundLabelValue,
    personValue,
    activityValue,
    changeValue,
    loiteringValue,
    burglaryValue,
    fightValue,
    doorEventsValue,
    playbackStats,
    playbackDuration,
    playbackProgress,
    playbackFps,
    playbackFrame,
    totalFrames,
  };
};

export const buildRecordingsByCamera = (completedRecordings = []) => completedRecordings
  .slice()
  .sort((a, b) => new Date(b.start_time) - new Date(a.start_time))
  .reduce((acc, recording) => {
    const key = recording.camera_id || 'unknown_camera';
    if (!acc[key]) {
      acc[key] = [];
    }
    acc[key].push(recording);
    return acc;
  }, {});

export const buildCameraRows = (recordingsByCamera = {}, validCameras = []) => Object.keys(recordingsByCamera)
  .map((cameraId) => {
    const cameraInfo = validCameras.find((cam) => cam.id === cameraId) || { id: cameraId, name: 'Unknown Camera' };
    return {
      cameraId,
      cameraName: cameraInfo.name,
      recordings: recordingsByCamera[cameraId],
    };
  })
  .sort((a, b) => a.cameraName.localeCompare(b.cameraName));

export const buildRowMetricsData = (recordings = [], zoomHours = 24, scrollOffsetHours = 0) => {
  const rowMetrics = recordings.map((recording, index) => {
    const metadata = getRecordingMetadata(recording);
    const timestampValue = getRecordingTimestampValue(recording, metadata);
    const parsedTimestamp = timestampValue ? new Date(timestampValue) : null;
    const hasValidTime = parsedTimestamp && !Number.isNaN(parsedTimestamp.getTime());
    const velocity = Number(metadata.vel);
    const bgDiff = getRecordingChangeValue(recording);
    const soundAlert = Number(metadata.sound_alert ?? -1);
    const soundLabel = metadata.sound_label || '';
    const duration = Number(recording.duration);
    const person = getRecordingPersonCount(recording);
    const hasChange = !!(metadata.change_detection);
    const changeDiff = getRecordingChangeValue(recording);

    return {
      id: recording.id,
      index,
      timestampMs: hasValidTime ? parsedTimestamp.getTime() : null,
      timeLabel: hasValidTime ? formatTimeInTimezone(parsedTimestamp) : '--:--',
      velocity: Number.isFinite(velocity) ? Math.max(0, velocity) : 0,
      bgDiff: Number.isFinite(bgDiff) ? Math.max(0, bgDiff) : 0,
      soundAlert: soundAlert >= 0 ? soundAlert : 0,
      soundLabel,
      duration: Number.isFinite(duration) ? Math.max(0, duration) : 0,
      person: Number.isFinite(person) ? Math.max(0, person) : 0,
      hasChange,
      changeDiff: Number.isFinite(changeDiff) ? Math.max(0, changeDiff) : 0,
    };
  });

  const validTimestamps = rowMetrics
    .map((metric) => metric.timestampMs)
    .filter((value) => Number.isFinite(value));

  const latestTimestampMs = validTimestamps.length > 0 ? Math.max(...validTimestamps) : Date.now();
  const earliestTimestampMs = validTimestamps.length > 0 ? Math.min(...validTimestamps) : Date.now();
  const totalDataSpanHours = Math.max(zoomHours, (latestTimestampMs - earliestTimestampMs) / (60 * 60 * 1000));
  const chartWindowMs = zoomHours * 60 * 60 * 1000;
  const chartEndMs = latestTimestampMs - (scrollOffsetHours * 60 * 60 * 1000);
  const chartStartMs = chartEndMs - chartWindowMs;

  const chartMetrics = rowMetrics
    .map((metric) => {
      const ts = Number(metric.timestampMs);
      if (!Number.isFinite(ts) || ts < chartStartMs || ts > chartEndMs) {
        return { ...metric, xPercent: null };
      }

      const normalized = ((chartEndMs - ts) / chartWindowMs) * 100;
      const xPercent = Math.max(0, Math.min(100, normalized));
      return { ...metric, xPercent };
    })
    .filter((metric) => metric.xPercent !== null);

  const chartMaxVelocity = Math.max(1, ...chartMetrics.map((metric) => metric.velocity));
  const chartMaxBgDiff = Math.max(1, ...chartMetrics.map((metric) => metric.bgDiff));
  const chartMaxSoundAlert = 3; // fixed 0-3 scale
  const chartMaxDuration = Math.max(1, ...chartMetrics.map((metric) => metric.duration));
  const chartMaxPerson = Math.max(1, ...chartMetrics.map((metric) => metric.person));
  const chartMaxChange = Math.max(1, ...chartMetrics.map((metric) => metric.changeDiff));

  const tickInterval = Math.max(1, Math.floor(zoomHours / 8)); // Show ~8 ticks max
  const tickCount = Math.floor(zoomHours / tickInterval) + 1;
  
  const axisTicks = Array.from({ length: tickCount }, (_, tickIndex) => {
    const hourOffset = tickIndex * tickInterval;
    const tickTs = chartEndMs - (hourOffset * 60 * 60 * 1000);
    return {
      xPercent: (hourOffset / zoomHours) * 100,
      label: formatTimeInTimezone(new Date(tickTs)),
      showLabel: tickIndex % Math.max(1, Math.floor(tickCount / 4)) === 0, // Show ~4 labels max
    };
  });

  return {
    chartMetrics,
    chartMaxVelocity,
    chartMaxBgDiff,
    chartMaxSoundAlert,
    chartMaxDuration,
    chartMaxPerson,
    chartMaxChange,
    axisTicks,
    totalDataSpanHours,
    latestTimestampMs,
    earliestTimestampMs,
  };
};

/**
 * Build metrics data for a single date (00:00–23:59), x-axis = time of day.
 * Returns metrics positioned as percentage of the 24h window (0% = 00:00, 100% = 24:00).
 */
export const buildDateMetricsData = (
  recordings = [],
  dateStr,
  timezoneOffset = DEFAULT_TIMEZONE_OFFSET,
) => {
  const [year, month, day] = String(dateStr).split('-').map(Number);
  const dayStart = Date.UTC(year, month - 1, day) - parseTimezoneOffset(timezoneOffset);
  const dayEnd = dayStart + 24 * 60 * 60 * 1000;
  const dayMs = 24 * 60 * 60 * 1000;

  const rowMetrics = recordings.map((recording, index) => {
    const metadata = getRecordingMetadata(recording);
    const timestampValue = getRecordingTimestampValue(recording, metadata);
    const parsedTimestamp = timestampValue
      ? parseTimestampInTimezone(timestampValue, timezoneOffset)
      : null;
    const hasValidTime = parsedTimestamp && !Number.isNaN(parsedTimestamp.getTime());
    const velocity = Number(metadata.vel);
    const bgDiff = getRecordingChangeValue(recording);
    const soundAlert = Number(metadata.sound_alert ?? -1);
    const soundLabel = metadata.sound_label || '';
    const activity = Number(metadata.activity ?? metadata.activity_percentage);
    const loitering = Number(metadata.loitering_score);
    const burglary = Number(metadata.burglary_score);
    const fight = Number(metadata.fight_score);
    const duration = Number(recording.duration);
    const person = getRecordingPersonCount(recording);

    return {
      id: recording.id,
      index,
      timestampMs: hasValidTime ? parsedTimestamp.getTime() : null,
      timeLabel: hasValidTime
        ? formatTimeInTimezone(parsedTimestamp, timezoneOffset)
        : '--:--',
      velocity: Number.isFinite(velocity) ? Math.max(0, velocity) : 0,
      bgDiff: Number.isFinite(bgDiff) ? Math.max(0, bgDiff) : 0,
      soundAlert: soundAlert >= 0 ? soundAlert : 0,
      soundLabel,
      activity: Number.isFinite(activity) ? Math.max(0, activity) : 0,
      loitering: Number.isFinite(loitering) ? Math.max(0, loitering) : 0,
      burglary: Number.isFinite(burglary) ? Math.max(0, burglary) : 0,
      fight: Number.isFinite(fight) ? Math.max(0, fight) : 0,
      duration: Number.isFinite(duration) ? Math.max(0, duration) : 0,
      person: Number.isFinite(person) ? Math.max(0, person) : 0,
    };
  });

  const chartMetrics = rowMetrics
    .filter(m => m.timestampMs != null && m.timestampMs >= dayStart && m.timestampMs < dayEnd)
    .map(metric => {
      const xPercent = ((dayEnd - metric.timestampMs) / dayMs) * 100;
      return { ...metric, xPercent: Math.max(0, Math.min(100, xPercent)) };
    });

  const chartMaxVelocity = Math.max(1, ...chartMetrics.map(m => m.velocity));
  const chartMaxBgDiff = Math.max(1, ...chartMetrics.map(m => m.bgDiff));
  const chartMaxSoundAlert = 3; // fixed 0-3 scale
  const chartMaxActivity = Math.max(1, ...chartMetrics.map(m => m.activity));
  const chartMaxLoitering = Math.max(1, ...chartMetrics.map(m => m.loitering));
  const chartMaxBurglary = Math.max(1, ...chartMetrics.map(m => m.burglary));
  const chartMaxFight = Math.max(1, ...chartMetrics.map(m => m.fight));
  const chartMaxDuration = Math.max(1, ...chartMetrics.map(m => m.duration));
  const chartMaxPerson = Math.max(1, ...chartMetrics.map(m => m.person));

  // Fixed 24h axis ticks every 3 hours (newest=left, oldest=right)
  const axisTicks = Array.from({ length: 9 }, (_, i) => {
    const hour = i * 3;
    return {
      xPercent: (hour / 24) * 100,
      label: `${String(24 - hour).padStart(2, '0')}:00`,
      showLabel: true,
    };
  });

  // Current time indicator (percentage of day elapsed)
  const now = Date.now();
  const nowPercent = now >= dayStart && now < dayEnd ? ((dayEnd - now) / dayMs) * 100 : null;

  return {
    chartMetrics,
    chartMaxVelocity,
    chartMaxBgDiff,
    chartMaxSoundAlert,
    chartMaxActivity,
    chartMaxLoitering,
    chartMaxBurglary,
    chartMaxFight,
    chartMaxDuration,
    chartMaxPerson,
    axisTicks,
    nowPercent,
  };
};
